  -- [Data Structures] SQRT.cpp: Mo's Algorithm for answering offline queries
  s("sqrt", {
    t({
      "#include <bits/stdc++.h>",
      "",
      "using namespace std;",
      "",
      "#define ar array",
      "#define ll long long",
      "",
      "const int MAX_N = 2e5 + 1;",
      "const int MOD = 1e9 + 7;",
      "const int INF = 1e9;",
      "const ll LINF = 1e18;",
      "",
      "struct query{",
      "    int SQRT = 500;",
      "    int l, r, id;",
      "    bool operator< (query b) {",
      "        query a = *this;",
      "        return ar<int,2>{a.l/SQRT, a.r} < ar<int,2>{b.l/SQRT, b.r};",
      "    }",
      "};",
      "",
      "int n, q, arr[MAX_N], ans[MAX_N], cnt[MAX_N], cur;",
      "query qs[MAX_N];",
      "",
      "void add(int idx) {",
      "    if (cnt[arr[idx]] == 0) cur++;",
      "    cnt[arr[idx]]++;",
      "}",
      " ",
      "void subtract(int idx) {",
      "    if (cnt[arr[idx]] == 1) cur--;",
      "    cnt[arr[idx]]--;",
      "}",
      "",
      "// compress used values from 1e9 to 2e5 ",
      "void compress() {",
      "    map<int, int> mp;",
      "    for (int i = 1; i <= n; i++) ",
      "        mp[arr[i]] = i;",
      "    for (int i = 1; i <= n; i++) ",
      "        arr[i] = mp[arr[i]];",
      "}",
      "",
      "void mo_algo() {",
      "    sort(qs + 1, qs + n + 1);",
      "    int curL = 0, curR = 0;",
      "    add(0);",
      "    for (int i = 1; i <= n; i++) {",
      "        int L = qs[i].l, R = qs[i].r;",
      "        while (curL < L) subtract(curL++);",
      "        while (curL > L) add(--curL);",
        "        while (curR < R) add(++curR);",
        "        while (curR > R) subtract(curR--);",
        "        ans[qs[i].id] = cur;",
        "    }",
        "}",
        "",
        "void solve() {",
        "    cin >> n >> q;",
        "    for (int i = 1; i <= n; i++) cin >> arr[i];",
        "    compress();",
        "    for (int i = 1; i <= q; i++) {",
        "        cin >> qs[i].l >> qs[i].r;",
        "        qs[i].id = i;",
        "    }",
        "    mo_algo();",
        "    for (int i = 1; i <= q; i++) ",
        "        cout << ans[i] << \"\\n\";",
        "}",
        "",
        "int main() {",
        "    ios_base::sync_with_stdio(0);",
        "    cin.tie(0); cout.tie(0);",
        "    // freopen(\"input.txt\", \"r\", stdin);",
        "    // freopen(\"output.txt\", \"w\", stdout);",
        "",
        "    int tc; tc = 1;",
        "    for (int t = 1; t <= tc; t++) {",
        "        // cout << \"Case #\" << t  << \": \";",
        "        solve();",
        "    }",
        "}"
      }),
      i(0),  -- Final cursor position
    }),

    -- [Segment Tree] Segment Tree (Lazy Propagation).cpp: Segment tree with lazy propagation for range sum query, range add update, range set update
    s("segtree_lazy", {
      t({
        "#include <bits/stdc++.h>",
        "",
        "using namespace std;",
        "",
        "#define ar array",
        "#define ll long long",
        "",
        "const int MAX_N = 2e5 + 1;",
        "const int MOD = 1e9 + 7;",
        "const int INF = 1e9;",
        "const ll LINF = 1e18;",
        "",
        "struct tdata {",
        "    ll sum, setval, addval;",
        "    bool lazyset;",
        "    tdata() {",
        "        sum = setval = addval = lazyset = 0;",
        "    }",
        "    tdata(ll val) {",
        "        sum = val;",
        "        setval = addval = lazyset = 0;",
        "    }",
        "    tdata(tdata l, tdata r) {",
        "        sum = l.sum + r.sum; ",
        "    }",
        "};",
        " ",
        "int n, q, arr[MAX_N];",
        "tdata st[4 * MAX_N];",
        " ",
        "void build(int node, int start, int end) {",
        "    if (start == end) {",
        "        st[node] = tdata(arr[start]);",
        "        return;",
        "    }",
        "    int mid = (start + end) / 2;",
        "    build(2 * node, start, mid);",
        "    build(2 * node + 1, mid + 1, end);",
        "    st[node].sum = st[2 * node].sum + st[2 * node + 1].sum;",
        "}",
        " ",
        "void down(int node, int start, int end) { ",
        "    int mid = (start + end) / 2;",
        "    if (st[node].lazyset) {",
        "        st[2 * node] = st[2 * node + 1] = st[node];",
        "        st[2 * node].sum = (st[node].setval + st[node].addval) * (mid - start + 1);",
        "        st[2 * node + 1].sum = (st[node].setval + st[node].addval) * (end - mid);",
        "    }",
        "    else {",
        "        st[2 * node].addval += st[node].addval;",
        "        st[2 * node + 1].addval += st[node].addval;",
        "        st[2 * node].sum += st[node].addval * (mid - start + 1);",
        "        st[2 * node + 1].sum += st[node].addval * (end - mid);",
        "    }",
        "    st[node].addval = st[node].setval = st[node].lazyset = 0;",
        "}",
        "",
        "// t = 1 means range add update, t = 2 means range set update",
        "void update(int node, int start, int end, int l, int r, ll val, int t) { ",
        "    if (r < start || end < l) return;",
        "    if (l <= start && end <= r) {",
        "        if (t == 2) {",
        "            st[node].setval = val;",
        "            st[node].lazyset = 1;",
        "            st[node].addval = 0;",
        "            st[node].sum = val * (end - start + 1);",
        "        }",
        "        else {",
        "            st[node].addval += val;",
        "            st[node].sum += val * (end - start + 1);",
        "        }",
        "        return;",
        "    }",
        "    down(node, start, end);",
        "    int mid = (start + end) / 2;",
        "    update(2 * node, start, mid, l, r, val, t);",
        "    update(2 * node + 1, mid + 1, end, l, r, val, t);",
        "    st[node].sum = st[2 * node].sum + st[2 * node + 1].sum;",
        "}",
        " ",
        "tdata query(int node, int start, int end, int l, int r) {",
        "    if (r < start || end < l) return tdata(0);",
        "    if (l <= start && end <= r) return st[node];",
        "    down(node, start, end);",
        "    int mid = (start + end) / 2;",
        "    return tdata(query(2 * node, start, mid, l, r), query(2 * node + 1, mid + 1, end, l, r));",
        "}",
        " ",
        "void solve() {",
        "    cin >> n >> q;",
        "    for (int i = 1; i <= n; i++) cin >> arr[i];",
        "    build(1, 1, n);",
        "    while (q--) {",
        "        int t, l, r; cin >> t >> l >> r;",
        "        if (t == 3) cout << query(1, 1, n, l, r).sum << \"\\n\";",
        "        else {",
        "            int x; cin >> x;",
        "            update(1, 1, n, l, r, x, t);",
        "        }",
        "    }",
        "}",
        "",
        "int main() {",
        "    ios_base::sync_with_stdio(0);",
        "    cin.tie(0); cout.tie(0);",
        "    // freopen(\"input.txt\", \"r\", stdin);",
        "    // freopen(\"output.txt\", \"w\", stdout);",
        "",
        "    int tc; tc = 1;",
        "    for (int t = 1; t <= tc; t++) {",
        "        // cout << \"Case #\" << t  << \": \";",
        "        solve();",
        "    }",
        "}"
      }),
      i(0),  -- Final cursor position
    }),

    -- [Segment Tree] Segment Tree (Persistent).cpp: Persistent segment tree for range sum query, point set update
    s("segtree_pers", {
      t({
        "#include <bits/stdc++.h>",
        "",
        "using namespace std;",
        "",
        "#define ar array",
        "#define ll long long",
        "",
        "const int MAX_N = 2e5 + 1;",
        "const int MOD = 1e9 + 7;",
        "const int INF = 1e9;",
        "const ll LINF = 1e18;",
        "",
        "struct tdata {",
        "    tdata *l, *r;",
        "    ll sum;",
        "    tdata() {}",
        "    tdata(tdata* l, tdata* r, int val) : l(l), r(r), sum(val) {}",
        "};",
        "",
        "int n, q, cnt, arr[MAX_N];",
        "tdata *ver[MAX_N];",
        "",
        "void build(tdata *node, int start, int end) {",
        "    if (start == end) {",
        "        node->sum = arr[start];",
        "        return;",
        "    }",
        "    node->l = new tdata(); node->r = new tdata();",
        "    int mid = (start + end) / 2;",
        "    build(node->l, start, mid);",
        "    build(node->r, mid + 1, end);",
        "    node->sum = node->l->sum + node->r->sum;",
        "}",
        "",
        "void update(tdata *node, int start, int end, int idx, int val) {",
        "    if (start == end) {",
        "        node->sum = val;",
        "        return;",
        "    }",
        "    int mid = (start + end) / 2;",
        "    if (idx <= mid) {",
        "        tdata *l = node->l;",
        "        node->l = new tdata(l->l, l->r, l->sum);",
        "        update(node->l, start, mid, idx, val);",
        "    }",
        "    else {",
        "        tdata *r = node->r;",
        "        node->r = new tdata(r->l, r->r, r->sum);",
        "        update(node->r, mid + 1, end, idx, val);",
        "    }",
        "    node->sum = node->l->sum + node->r->sum;",
        "}",
        "",
        "ll query(tdata *node, int start, int end, int l, int r) {",
        "    if (r < start || end < l) return 0;",
        "    if (l <= start && end <= r) return node->sum;",
        "    int mid = (start + end) / 2;",
        "    return query(node->l, start, mid, l, r) + query(node->r, mid + 1, end, l, r);",
        "}",
        "",
        "void solve() {",
        "    cin >> n >> q;",
        "    for (int i = 1; i <= n; i++) cin >> arr[i];",
        "    ver[++cnt] = new tdata();",
        "    build(ver[cnt], 1, n);",
        "    while (q--) {",
        "        int t, k; cin >> t >> k;",
        "        if (t == 1) {",
        "            int a, x; cin >> a >> x;",
        "            update(ver[k], 1, n, a, x);",
        "        }",
        "        else if (t == 2) {",
        "            int a, b; cin >> a >> b;",
        "            cout << query(ver[k], 1, n, a, b) << \"\\n\";",
        "        }",
        "        else {",
        "            ver[++cnt] = new tdata(ver[k]->l, ver[k]->r, ver[k]->sum);",
        "        }",
        "    }",
        "}",
        "",
        "int main() {",
        "    ios_base::sync_with_stdio(0);",
        "    cin.tie(0); cout.tie(0);",
        "    // freopen(\"input.txt\", \"r\", stdin);",
        "    // freopen(\"output.txt\", \"w\", stdout);",
        "",
        "    int tc; tc = 1;",
        "    for (int t = 1; t <= tc; t++) {",
        "        // cout << \"Case #\" << t  << \": \";",
        "        solve();",
        "    }",
        "}"
      }),
      i(0),  -- Final cursor position
    }),

    -- [Segment Tree] Segment Tree (Recursive).cpp: Segment tree for range minimum query, point set update
    s("segtree_recu", {
      t({
        "#include <bits/stdc++.h>",
        "",
        "using namespace std;",
        "",
        "#define ar array",
        "#define ll long long",
        "",
        "const int MAX_N = 2e5 + 1;",
        "const int MOD = 1e9 + 7;",
        "const int INF = 1e9;",
        "const ll LINF = 1e18;",
        "",
        "int n, q, arr[MAX_N], st[4 * MAX_N];",
        " ",
        "void build(int node, int start, int end) {",
        "    if (start == end) {",
        "        st[node] = arr[start];",
        "        return;",
        "    }",
        "    int mid = (start + end) / 2;",
        "    build(2 * node, start, mid);",
        "    build(2 * node + 1, mid + 1, end);",
        "    st[node] = min(st[2 * node], st[2 * node + 1]);",
        "}",
        " ",
        "void update(int node, int start, int end, int idx, int val) {",
        "    if (start == end) {",
        "        arr[idx] = val;",
        "        st[node] = val;",
        "        return;",
        "    }",
        "    int mid = (start + end) / 2;",
        "    if (idx <= mid) update(2 * node, start, mid, idx, val);",
        "    else update(2 * node + 1, mid + 1, end, idx, val);",
        "    st[node] = min(st[2 * node], st[2 * node + 1]);",
        "}",
        "",
        "int query(int node, int start, int end, int l, int r) {",
        "    if (start > r || end < l) return INF;",
        "    if (l <= start && end <= r) return st[node];",
        "    int mid = (start + end) / 2;",
        "    return min(query(2 * node, start, mid, l, r), query(2 * node + 1, mid + 1, end, l, r)); ",
        "}",
        " ",
        "void solve() {",
        "    cin >> n >> q;",
        "    for (int i = 1; i <= n; i++) cin >> arr[i];",
        "    build(1, 1, n);",
        "    while (q--) {",
        "        int t; cin >> t;",
        "        if (t == 1) {",
        "            int k, u; cin >> k >> u;",
        "            update(1, 1, n, k, u);",
        "        }",
        "        else {",
        "            int l, r; cin >> l >> r;",
        "            cout << query(1, 1, n, l, r) << \"\\n\";",
        "        }",
        "    }",
        "}",
        "",
        "int main() {",
        "    ios_base::sync_with_stdio(0);",
        "    cin.tie(0); cout.tie(0);",
        "    // freopen(\"input.txt\", \"r\", stdin);",
        "    // freopen(\"output.txt\", \"w\", stdout);",
        "",
        "    int tc; tc = 1;",
        "    for (int t = 1; t <= tc; t++) {",
        "        // cout << \"Case #\" << t  << \": \";",
        "        solve();",
        "    }",
        "}"
      }),
      i(0),  -- Final cursor position
    }),

    -- [Segment Tree] Segment Tree Beats.cpp: Segment tree beats for chmax, chmin and add range updates
    s("segtree", {
      t({
        "#include <bits/stdc++.h>",
        "",
        "using namespace std;",
        "",
        "#define ar array",
        "#define ll long long",
        "",
        "const int MAX_N = 1e5 + 1;",
        "const int MOD = 1e9 + 7;",
        "const int INF = 1e9;",
        "const ll LINF = 1e18;",
        "",
        "struct segtree { ",
        "    struct tdata {",
        "        ll sum, addval, mx, mx2, mx_cnt, mn, mn2, mn_cnt;",
        "        tdata(): sum(), addval(), mx(-LINF), mx2(-LINF), mx_cnt(), mn(LINF), mn2(LINF), mn_cnt() {}",
        "        tdata(ll val): sum(val), addval(), mx(val), mx2(-LINF), mx_cnt(1), mn(val), mn2(LINF), mn_cnt(1) {}",
        "        tdata(tdata l, tdata r) {",
        "            sum = l.sum + r.sum;",
        "            if (l.mx > r.mx) {",
        "                mx = l.mx;",
        "                mx2 = max(l.mx2, r.mx);",
        "                mx_cnt = l.mx_cnt;",
        "            }",
        "            else if (r.mx > l.mx) {",
        "                mx = r.mx;",
        "                mx2 = max(r.mx2, l.mx);",
        "                mx_cnt = r.mx_cnt;",
        "            }",
        "            else {",
        "                mx = l.mx;",
        "                mx2 = max(l.mx2, r.mx2);",
        "                mx_cnt = l.mx_cnt + r.mx_cnt;",
        "            }",
        "            if (l.mn < r.mn) {",
        "                mn = l.mn;",
        "                mn2 = min(l.mn2, r.mn);",
        "                mn_cnt = l.mn_cnt;",
        "            }",
        "            else if (r.mn < l.mn) {",
        "                mn = r.mn;",
        "                mn2 = min(r.mn2, l.mn);",
        "                mn_cnt = r.mn_cnt;",
        "            }",
        "            else {",
        "                mn = l.mn;",
        "                mn2 = min(l.mn2, r.mn2);",
        "                mn_cnt = l.mn_cnt + r.mn_cnt;",
        "            }",
        "        }",
        "    };",
        "    int ln(int node) {return 2 * node;}",
        "    int rn(int node) {return 2 * node + 1;}",
        "    int n; vector<tdata> st;",
        "    segtree(int n): n(n), st(4 * n) {}",
        "    segtree(vector<ll> &arr) : segtree(arr.size()) {",
        "        build(arr, 1, 0, n - 1);",
        "    }",
        "    void apply_add(int node, int start, int end, ll val) {",
        "        st[node].sum += val * (end - start + 1);",
        "        st[node].mx += val;",
        "        st[node].mn += val;",
        "        if (st[node].mx2 != -LINF) st[node].mx2 += val; ",
        "        if (st[node].mn2 != LINF) st[node].mn2 += val; ",
        "        st[node].addval += val;",
        "    }",
        "    void apply_min(int node, ll val) {",
        "        st[node].sum += (val - st[node].mx) * st[node].mx_cnt;",
        "        st[node].mx = val;",
        "        if (val < st[node].mn) st[node].mn = val;",
        "        else if (val < st[node].mn2) st[node].mn2 = val;",
        "    }",
        "    void apply_max(int node, ll val) {",
        "        st[node].sum += (val - st[node].mn) * st[node].mn_cnt;",
        "        st[node].mn = val;",
        "        if (val > st[node].mx) st[node].mx = val;",
        "        else if (val > st[node].mx2) st[node].mx2 = val;",
        "    }",
        "    void combine(int node) {",
        "        st[node].sum = st[ln(node)].sum + st[rn(node)].sum;",
        "        if (st[ln(node)].mx > st[rn(node)].mx) {",
        "            st[node].mx = st[ln(node)].mx;",
        "            st[node].mx2 = max(st[ln(node)].mx2, st[rn(node)].mx);",
        "            st[node].mx_cnt = st[ln(node)].mx_cnt;",
        "        }",
        "        else if (st[rn(node)].mx > st[ln(node)].mx) {",
        "            st[node].mx = st[rn(node)].mx;",
        "            st[node].mx2 = max(st[rn(node)].mx2, st[ln(node)].mx);",
        "            st[node].mx_cnt = st[rn(node)].mx_cnt;",
        "        }",
        "        else {",
        "            st[node].mx = st[ln(node)].mx;",
        "            st[node].mx2 = max(st[ln(node)].mx2, st[rn(node)].mx2);",
        "            st[node].mx_cnt = st[ln(node)].mx_cnt + st[rn(node)].mx_cnt;",
        "        }",
        "        if (st[ln(node)].mn < st[rn(node)].mn) {",
        "            st[node].mn = st[ln(node)].mn;",
        "            st[node].mn2 = min(st[ln(node)].mn2, st[rn(node)].mn);",
        "            st[node].mn_cnt = st[ln(node)].mn_cnt;",
        "        }",
        "        else if (st[rn(node)].mn < st[ln(node)].mn) {",
        "            st[node].mn = st[rn(node)].mn;",
        "            st[node].mn2 = min(st[rn(node)].mn2, st[ln(node)].mn);",
        "            st[node].mn_cnt = st[rn(node)].mn_cnt;",
        "        }",
        "        else {",
        "            st[node].mn = st[ln(node)].mn;",
        "            st[node].mn2 = min(st[ln(node)].mn2, st[rn(node)].mn2);",
        "            st[node].mn_cnt = st[ln(node)].mn_cnt + st[rn(node)].mn_cnt;",
        "        }",
        "    }",
        "    void propagate(int node, int start, int end) {",
        "        if (start == end) return;",
        "        int mid = (start + end) / 2;",
        "        if (st[node].addval) {",
        "            apply_add(ln(node), start, mid, st[node].addval);",
        "            apply_add(rn(node), mid + 1, end, st[node].addval);",
        "            st[node].addval = 0;",
        "        }",
        "        if (st[node].mx < st[ln(node)].mx) apply_min(ln(node), st[node].mx);",
        "        if (st[node].mx < st[rn(node)].mx) apply_min(rn(node), st[node].mx);",
        "        if (st[node].mn > st[ln(node)].mn) apply_max(ln(node), st[node].mn);",
        "        if (st[node].mn > st[rn(node)].mn) apply_max(rn(node), st[node].mn);",
        "    }",
        "    void build(vector<ll> &arr, int node, int start, int end) {",
        "        if (start == end) {",
        "            st[node] = tdata(arr[start]);",
        "            return;",
        "        }",
        "        int mid = (start + end) / 2;",
        "        build(arr, ln(node), start, mid);",
        "        build(arr, rn(node), mid + 1, end);",
        "        combine(node);",
        "    }",
        "    void update_add(int node, int start, int end, int l, int r, ll val) {",
        "        propagate(node, start, end);",
        "        if (r < start || end < l) return;",
        "        if (l <= start && end <= r) {",
        "            apply_add(node, start, end, val);",
        "            return;",
        "        }",
        "        int mid = (start + end) / 2;",
        "        update_add(ln(node), start, mid, l, r, val);",
        "        update_add(rn(node), mid + 1, end, l, r, val);",
        "        combine(node);",
        "    }",
        "    void update_min(int node, int start, int end, int l, int r, ll val) {",
        "        propagate(node, start, end);",
        "        if (r < start || end < l || st[node].mx <= val) return;",
        "        if (l <= start && end <= r && st[node].mx2 < val) {",
        "            apply_min(node, val);",
        "            return;",
        "        }",
        "        int mid = (start + end) / 2;",
        "        update_min(ln(node), start, mid, l, r, val);",
        "        update_min(rn(node), mid + 1, end, l, r, val);",
        "        combine(node);",
        "    }",
        "    void update_max(int node, int start, int end, int l, int r, ll val) {",
        "        propagate(node, start, end);",
        "        if (r < start || end < l || st[node].mn >= val) return;",
        "        if (l <= start && end <= r && st[node].mn2 > val) {",
        "            apply_max(node, val);",
        "            return;",
        "        }",
        "        int mid = (start + end) / 2;",
        "        update_max(ln(node), start, mid, l, r, val);",
        "        update_max(rn(node), mid + 1, end, l, r, val);",
        "        combine(node);",
        "    }",
        "    tdata query(int node, int start, int end, int l, int r) {",
        "        propagate(node, start, end);",
        "        if (r < start || end < l) return tdata();",
        "        if (l <= start && end <= r) return st[node];",
        "        int mid = (start + end) / 2;",
        "        return tdata(query(ln(node), start, mid, l, r), query(rn(node), mid + 1, end, l, r));",
        "    }",
        "    void update_add(int l, int r, ll val) {update_add(1, 0, n - 1, l, r, val);}",
        "    void update_min(int l, int r, ll val) {update_min(1, 0, n - 1, l, r, val);}",
        "    void update_max(int l, int r, ll val) {update_max(1, 0, n - 1, l, r, val);}",
        "    tdata query(int l, int r) {return query(1, 0, n - 1, l, r);}",
        "};",
        "",
        "void solve() {",
        "    int n, q; cin >> n >> q;",
        "    vector<ll> a(n);",
        "    for (int i = 0; i < n; i++) cin >> a[i];",
        "    segtree st(a);",
        "    while (q--) {",
        "        int t, l, r; cin >> t >> l >> r; r--;",
        "        if (t == 0) {",
        "            ll x; cin >> x;",
        "            st.update_min(l, r, x);",
        "        }",
        "        else if (t == 1) {",
        "            ll x; cin >> x;",
        "            st.update_max(l, r, x);",
        "        }",
        "        else if (t == 2) {",
        "            ll x; cin >> x;",
        "            st.update_add(l, r, x);",
        "        }",
        "        else {",
        "            cout << st.query(l, r).sum << \"\\n\";",
        "        }",
        "    }",
        "}",
        "",
        "int main() {",
        "    ios_base::sync_with_stdio(0);",
        "    cin.tie(0); cout.tie(0);",
        "    // freopen(\"input.txt\", \"r\", stdin);",
        "    // freopen(\"output.txt\", \"w\", stdout);",
        "",
        "    int tc = 1;",
        "    // cin >> tc;",
        "    for (int t = 1; t <= tc; t++) {",
        "        // cout << \"Case #\" << t  << \": \";",
        "        solve();",
        "    }",
        "}"
      }),
      i(0),  -- Final cursor position
    }),

    -- [Data Structures] Sparse Table.cpp: Answer range query for static array
    s("sparse", {
      t({
        "#include <bits/stdc++.h>",
        "",
        "using namespace std;",
        "",
        "#define ar array",
        "#define ll long long",
        "",
        "const int MAX_N = 2e5 + 1;",
        "const int MOD = 1e9 + 7;",
        "const int INF = 1e9;",
        "const ll LINF = 1e18;",
        "",
        "const int MAX_L = 18;",
        "",
        "int n, q;",
        "int arr[MAX_N], dp[MAX_N][MAX_L];",
        " ",
        "void build_sparse_table() {",
        "    for (int i = 1; i <= n; i++)",
        "        dp[i][0] = arr[i];",
        "    for (int j = 1; j < MAX_L; j++)",
        "        for (int i = 1; i + (1 << j) <= n + 1; i++)",
        "            dp[i][j] = min(dp[i][j - 1], dp[i + (1 << (j - 1))][j - 1]);",
        "            // dp[i][j] = dp[i][j - 1] ^ dp[i + (1 << (j - 1))][j - 1];",
        "}",
        "",
        "int lg(int x) {",
        "    return 32 - __builtin_clz(x) - 1;",
        "}",
        "",
        "int min_query(int l, int r) { // O(1)",
        "    int k = lg(r - l + 1);",
        "    return min(dp[l][k], dp[r - (1 << k) + 1][k]);",
        "}",
        "",
        "int xor_query(int l, int r) { // O(logn)",
        "    int k = r - l + 1, ans = 0;",
        "    for (int i = 0; i < MAX_L; i++) {",
        "        if (k & (1 << i)) {",
        "            ans ^= dp[l][i];",
        "            l += (1 << i);",
        "        }",
        "    }",
        "    return ans;",
        "}",
        "",
        "void solve() {",
        "    cin >> n >> q;",
        "    for (int i = 1; i <= n; i++) cin >> arr[i];",
        "    build_sparse_table();",
        "    while (q--) {",
        "        int l, r; cin >> l >> r;",
        "        cout << min_query(l, r) << \"\\n\";",
        "    }",
        "}",
        "",
        "int main() {",
        "    ios_base::sync_with_stdio(0);",
        "    cin.tie(0); cout.tie(0);",
        "    // freopen(\"input.txt\", \"r\", stdin);",
        "    // freopen(\"output.txt\", \"w\", stdout);",
        "",
        "    int tc; tc = 1;",
        "    for (int t = 1; t <= tc; t++) {",
        "        // cout << \"Case #\" << t  << \": \";",
        "        solve();",
        "    }",
        "}"
      }),
      i(0),  -- Final cursor position
    }),

    -- [Data Structures] Suffix Array.cpp: Suffix Array: storing all suffixes of a string, useful for many string-related problems
    s("suffix", {
      t({
        "#include <bits/stdc++.h>",
        "",
        "using namespace std;",
        "",
        "#define ar array",
        "#define ll long long",
        "",
        "const int MAX_N = 1e5 + 1;",
        "const int MOD = 1e9 + 7;",
        "const int INF = 1e9;",
        "const ll LINF = 1e18;",
        "",
        "",
        "",
        "void solve() {",
        "    string s; cin >> s; s += \"$\";",
        "    int n = s.size();",
        "    vector<int> p(n), c(n);",
        "    vector<pair<char,int>> a(n);",
        "    for (int i = 0; i < n; i++) a[i] = {s[i], i};",
        "    sort(a.begin(), a.end());",
        "    for (int i = 0; i < n; i++) p[i] = a[i].second;",
        "    for (int i = 1; i < n; i++) c[p[i]] = (a[i].first == a[i - 1].first) ? c[p[i - 1]] : c[p[i - 1]] + 1;",
        "    for (int k = 0; (1 << k) < n; k++) {",
        "        for (int i = 0; i < n; i++) p[i] = (p[i] - (1 << k) + n) % n;",
        "        vector<int> np(n), nc(n), cnt(n), pos(n);",
        "        for (int x : p) cnt[c[x]]++;",
        "        for (int i = 1; i < n; i++) pos[i] = pos[i - 1] + cnt[i - 1];",
        "        for (int x : p) np[pos[c[x]]++] = x;",
        "        p = np;",
        "        for (int i = 1; i < n; i++) {",
        "            pair<int,int> cur = {c[p[i]], c[(p[i] + (1 << k)) % n]};",
        "            pair<int,int> pre = {c[p[i - 1]], c[(p[i - 1] + (1 << k)) % n]};",
        "            nc[p[i]] = (cur == pre) ? nc[p[i - 1]] : nc[p[i - 1]] + 1;             ",
        "        }",
        "        c = nc;",
        "    } ",
        "    vector<int> lcp(n);",
        "    for (int i = 0, k = 0; i < n - 1; i++, k = max(k - 1, 0)) {",
        "        int pi = c[i], j = p[pi - 1];",
        "        while (s[i + k] == s[j + k]) k++;",
        "        lcp[pi] = k;",
        "    }",
        "    ",
        "    ll ans = 0;",
        "    for (int i = 0; i < n; i++) ans += (n - p[i] - 1) - lcp[i]; ",
        "    cout << ans << \"\\n\";",
        "}",
        "",
        "int main() {",
        "    ios_base::sync_with_stdio(0);",
        "    cin.tie(0); cout.tie(0);",
        "    // freopen(\"input.txt\", \"r\", stdin);",
        "    // freopen(\"output.txt\", \"w\", stdout);",
        "",
        "    int tc; cin >> tc;",
        "    for (int t = 1; t <= tc; t++) {",
        "        // cout << \"Case #\" << t  << \": \";",
        "        solve();",
        "    }",
        "}"
      }),
      i(0),  -- Final cursor position
    }),

    -- [Data Structures] Treap.cpp: Treap data structure supporting split and merge function
    s("treap", {
      t({
        "#include <bits/stdc++.h>",
        "",
        "using namespace std;",
        "",
        "#define ar array",
        "#define ll long long",
        "",
        "const int MAX_N = 1e5 + 1;",
        "const int MOD = 1e9 + 7;",
        "const int INF = 1e9;",
        "const ll LINF = 1e18;",
        "",
        "mt19937 rng(chrono::steady_clock::now().time_since_epoch().count());",
        "struct tdata {",
        "    int val, pri, sz;",
        "    tdata *ln, *rn;",
        "    tdata(int val): val(val), pri(rng()), sz(1), ln(), rn() {} ",
        "};",
        "int sz(tdata *node) {return node ? node->sz : 0;}",
        "void propagate(tdata *node) {",
        "    if (!node) return;",
        "}",
        "void combine(tdata *node) {",
        "    if (!node) return;",
        "    propagate(node->ln); propagate(node->rn);",
        "    node->sz = sz(node->ln) + sz(node->rn) + 1;",
        "}",
        "void heapify(tdata *node) {",
        "    if (!node) return;",
        "    auto mx = node;",
        "    if (node->ln && node->ln->pri > node->pri) mx = node;",
        "    if (node->rn && node->rn->pri > node->pri) mx = node;",
        "    if (node != mx) {",
        "        swap(node->pri, mx->pri);",
        "        heapify(mx);",
        "    }",
        "}",
        "tdata* build(vector<int> &arr, int start, int end) {",
        "    if (start > end) return NULL;",
        "    int mid = (start + end) / 2;",
        "    auto node = new tdata(arr[mid]);",
        "    node->ln = build(arr, start, mid - 1);",
        "    node->rn = build(arr, mid + 1, end);",
        "    heapify(node); combine(node);",
        "    return node;",
        "}",
        "void split(tdata *node, tdata *&ln, tdata *&rn, int k) { // k nodes to ln",
        "    propagate(node);",
        "    if (!node) {",
        "        ln = rn = NULL;",
        "        return;",
        "    }",
        "    if (sz(node->ln) >= k) split(node->ln, ln, node->ln, k), rn = node;",
        "    else split(node->rn, node->rn, rn, k - sz(node->ln) - 1), ln = node;",
        "    combine(node);",
        "}",
        "void merge(tdata *&node, tdata *ln, tdata *rn) {",
        "    propagate(ln); propagate(rn);",
        "    if (!ln || !rn) {",
        "        node = ln ? ln : rn;",
        "        return;",
        "    }",
        "    if (ln->pri > rn->pri) merge(ln->rn, ln->rn, rn), node = ln;",
        "    else merge(rn->ln, ln, rn->ln), node = rn;",
        "    combine(node);",
        "}",
        "void print(tdata *node) {",
        "    if (!node) return;",
        "    print(node->ln);",
        "    cout << node->val << \" \";",
        "    print(node->rn);",
        "}",
        "",
        "void solve() {",
        "    int n; cin >> n;",
        "    vector<int> arr(n);",
        "    iota(arr.begin(), arr.end(), 1);",
        "    auto tr = build(arr, 0, n - 1);",
        "    for (int i = 0; i < n; i++) {",
        "        int a, b; cin >> a >> b; ",
        "        if (a >= b) continue;",
        "        int len = min(b - a, n - b + 1);",
        "        tdata *p1, *p2, *p3, *p4, *p5;",
        "        split(tr, p3, p4, b - 1);",
        "        split(p4, p4, p5, len);",
        "        split(p3, p1, p2, a - 1);",
        "        split(p2, p2, p3, len);",
        "        merge(tr, p1, p4);",
        "        merge(tr, tr, p3);",
        "        merge(tr, tr, p2);",
        "        merge(tr, tr, p5);",
        "    }",
        "    print(tr);",
        "    cout << \"\\n\";",
        "}",
        "",
        "int main() {",
        "    ios_base::sync_with_stdio(0);",
        "    cin.tie(0); cout.tie(0);",
        "    // freopen(\"input.txt\", \"r\", stdin);",
        "    // freopen(\"output.txt\", \"w\", stdout);",
        "",
        "    int tc = 1;",
        "    // cin >> tc;",
        "    for (int t = 1; t <= tc; t++) {",
        "        // cout << \"Case #\" << t  << \": \";",
        "        solve();",
        "    }",
        "}"
      }),
      i(0),  -- Final cursor position
    }),

    -- [Data Structures] Tree Query.cpp: Query on tree using eulerian ordering and fenwick tree
    s("tree_query", {
      t({
        "#include <bits/stdc++.h>",
        "",
        "using namespace std;",
        "",
        "#define ar array",
        "#define ll long long",
        "",
        "const int MAX_N = 2e5 + 1;",
        "const int MOD = 1e9 + 7;",
        "const int INF = 1e9;",
        "const ll LINF = 1e18;",
        "",
        "#define LSOne(S) ((S) & (-S))",
        "",
        "int n, q, arr[MAX_N], tin[MAX_N], tout[MAX_N], timer;",
        "ll ft[2 * MAX_N];",
        "vector<int> adj[MAX_N];",
        " ",
        "void update(int x, int v) {",
        "    for (; x <= 2 * n; x += LSOne(x))",
        "        ft[x] += v;",
        "}",
        " ",
        "ll sum(int x) {",
        "    ll res = 0;",
        "    for (; x; x -= LSOne(x))",
        "        res += ft[x];",
        "    return res;",
        "}",
        " ",
        "ll rsq(int a, int b) {",
        "    return sum(b) - sum(a - 1);",
        "}",
        " ",
        "void dfs(int u, int p = 0) {",
        "    tin[u] = ++timer;",
        "    for (int v : adj[u]) {",
        "        if (v != p) {",
        "            dfs(v, u);",
        "        }",
        "    }",
        "    tout[u] = ++timer;",
        "}",
        " ",
        "void solve() {",
        "    cin >> n >> q;",
        "    for (int i = 1; i <= n; i++) cin >> arr[i];",
        "    for (int i = 0; i < n - 1; i++) {",
        "        int u, v; cin >> u >> v;",
        "        adj[u].push_back(v);",
        "        adj[v].push_back(u);",
        "    }",
        "    dfs(1);",
        "    for (int i = 1; i <= n; i++) {",
        "        update(tin[i], arr[i]);",
        "        update(tout[i], arr[i]);",
        "    }",
        "    while (q--) {",
        "        int t; cin >> t;",
        "        if (t == 1) {",
        "            int s, x; cin >> s >> x;",
        "            update(tin[s], x - arr[s]);",
        "            update(tout[s], x - arr[s]);",
        "            arr[s] = x;",
        "        }",
        "        else {",
        "            int s; cin >> s;",
        "            cout << rsq(tin[s], tout[s]) / 2 << \"\\n\";",
        "        }",
        "    }",
        "}",
        "",
        "int main() {",
        "    ios_base::sync_with_stdio(0);",
        "    cin.tie(0); cout.tie(0);",
        "    // freopen(\"input.txt\", \"r\", stdin);",
        "    // freopen(\"output.txt\", \"w\", stdout);",
        "",
        "    int tc; tc = 1;",
        "    for (int t = 1; t <= tc; t++) {",
        "        // cout << \"Case #\" << t  << \": \";",
        "        solve();",
        "    }",
        "}"
      }),
      i(0),  -- Final cursor position
    }),

    -- [Data Structures] Trie.cpp: Prefix tree: storing strings based on their common prefix
    s("trie", {
      t({
        "#include <bits/stdc++.h>",
        "",
        "using namespace std;",
        "",
        "#define ar array",
        "#define ll long long",
        "",
        "const int MAX_N = 1e5 + 1;",
        "const int MOD = 1e9 + 7;",
        "const int INF = 1e9;",
        "const ll LINF = 1e18;",
        "",
        "const int MAX_S = 2e6; // total number of characters in all strings",
        "const int MAX_C = 26; // total number of distinct characters ",
        "",
        "int N, K, num, ans;",
        "int trie[MAX_S][MAX_C], cnt[MAX_S];",
        "",
        "// initially all values in trie are 0 (not allocated)",
        "// cnt[u] = number of strings that end at node u in the trie => this is to mark the end of a string in the trie",
        "// \"num\" stores the total number of allocated nodes in the trie",
        "",
        "void dfs(int u = 0, int d = 0) {",
        "    for (int v = 0; v < 26; v++) {",
        "        if (trie[u][v]) {",
        "            dfs(trie[u][v], d + 1);",
        "            // now cnt[u] stores the total number of strings that has a common prefix from the root to node u",
        "            cnt[u] += cnt[trie[u][v]];",
        "        }",
        "    }",
        "    // greedily dividing into groups of K",
        "    while (cnt[u] >= K) { ",
        "        cnt[u] -= K;",
        "        ans += d;",
        "    }",
        "}",
        "",
        "// insert a string into the trie",
        "void insert(string s) {",
        "    // start at the root node",
        "    int u = 0; ",
        "    for (char c : s) {",
        "        // if this node has not been allocated, then allocate the node and increase num by 1",
        "        if (!trie[u][c - 'A']) trie[u][c - 'A'] = ++num; ",
        "        // move to the next node",
        "        u = trie[u][c - 'A']; ",
        "    }",
        "    // mark the end of string",
        "    cnt[u]++; ",
        "}",
        "",
        "// check if a string exist in the trie",
        "bool search(string s) { ",
        "    int u = 0;",
        "    for (char c : s) {",
        "        if (!trie[u][c - 'A']) return false;",
        "        u = trie[u][c - 'A'];",
        "    }",
        "    return cnt[u] > 0;",
        "}",
        "",
        "void solve() {",
        "    // need to reset after each test case",
        "    ans = 0; num = 0;",
        "    memset(trie, 0, sizeof trie);",
        "    memset(cnt, 0, sizeof cnt);",
        "",
        "    cin >> N >> K;",
        "    for (int i = 0; i < N; i++) {",
        "        string s; cin >> s;",
        "        insert(s);",
        "    }",
        "    dfs();",
        "    cout << ans << \"\\n\";",
        "}",
        "",
        "int main() {",
        "    ios_base::sync_with_stdio(0);",
        "    cin.tie(0); cout.tie(0);",
        "    // freopen(\"input.txt\", \"r\", stdin);",
        "    // freopen(\"output.txt\", \"w\", stdout);",
        "",
        "    int tc; cin >> tc;",
        "    for (int t = 1; t <= tc; t++) {",
        "        cout << \"Case #\" << t  << \": \";",
        "        solve();",
        "    }",
        "}"
      }),
      i(0),  -- Final cursor position
    }),

