    -- [Dynamic Programming] Deque Trick.cpp: Optimise from O(NK^2) to O(NK) by answering min/max queries among k consecutive elements in O(1) in 
    s("deque_trick", {
      t({
        "#include <bits/stdc++.h>",
        "",
        "using namespace std;",
        "",
        "#define ar array",
        "#define ll long long",
        "",
        "const int MAX_N = 1e5 + 1;",
        "const ll MOD = 1e9 + 7;",
        "const ll INF = 1e9;",
        "",
        "",
        "",
        "void solve() {",
        "    int n, k, x; cin >> n >> k >> x;",
        "    vector<int> a(n + 1);",
        "    for (int i = 1; i <= n; i++) cin >> a[i];",
        "    ll dp[n + 1][x + 1]; // dp[i][j] = answer using j pictures from the first i-th pictures",
        "    memset(dp, -0x3f, sizeof dp);",
        "    dp[0][0] = 0;",
        "    for (int j = 1; j <= x; j++) {",
        "        deque<ar<ll,2>> dq; // {id, value}",
        "        dq.push_back({j - 1, dp[j - 1][j - 1]});",
        "        for (int i = j; i <= n; i++) {",
        "            while (dq.size() && dq.front()[0] < i - k) dq.pop_front();",
        "            dp[i][j] = dq.front()[1] + a[i];",
        "            while (dq.size() && dp[i][j - 1] >= dq.back()[1]) dq.pop_back();",
        "            dq.push_back({i, dp[i][j - 1]});",
        "        }",
        "",
        "    }",
        "    ll ans = -1;",
        "    for (int i = 0; i < k; i++) ans = max(ans, dp[n - i][x]);",
        "    cout << ans << \"\\n\";",
        "}",
        "",
        "int main() {",
        "    ios_base::sync_with_stdio(0);",
        "    cin.tie(0); cout.tie(0);",
        "    int tc = 1; ",
        "    // cin >> tc;",
        "    for (int t = 1; t <= tc; t++) {",
        "        // cout << \"Case #\" << t  << \": \";",
        "        solve();",
        "    }",
        "}"
      }),
      i(0),  -- Final cursor position
    }),

    -- [Dynamic Programming] Digit DP.cpp: Find the sum of the digits of the numbers between a and b (0 <= a <= b <= 1e9)
    s("digit_dp", {
      t({
        "#include <bits/stdc++.h>",
        "",
        "using namespace std;",
        "",
        "#define ar array",
        "#define ll long long",
        "",
        "const int MAX_N = 1e5 + 1;",
        "const int MOD = 1e9 + 7;",
        "const int INF = 1e9;",
        "const ll LINF = 1e18;",
        "",
        "vector<int> num;",
        "ll dp[10][9 * 10][2];",
        "",
        "// dp[pos][sum][flag]",
        "// pos = current position, starting from the left (0-index)",
        "// sum = sum of all digits till the given position",
        "// flag = the number we are building has already become smaller than b? [0 = no, 1 = yes]",
        "",
        "ll memo(int pos, int sum, int flag) {",
        "    if (pos == num.size()) return sum;",
        "    if (dp[pos][sum][flag] != -1) return dp[pos][sum][flag];",
        "",
        "    ll res = 0;",
        "    int lmt = (flag) ? 9 : num[pos];",
        "    for (int i = 0; i <= lmt; i++) {",
        "        int next_flag = (i < lmt) ? 1 : flag;",
        "        res += memo(pos + 1, sum + i, next_flag);",
        "    }",
        "    return dp[pos][sum][flag] = res;",
        "}",
        "",
        "ll calc(int n) {",
        "    num.clear();",
        "    while (n) {",
        "        num.push_back(n % 10);",
        "        n /= 10;",
        "    }",
        "    reverse(num.begin(), num.end());",
        "    memset(dp, -1, sizeof dp);",
        "    return memo(0, 0, 0);",
        "}",
        "",
        "void solve() {",
        "    while (true) {",
        "        int a, b; cin >> a >> b;",
        "        if (a == -1 && b == -1) return;",
        "        cout << calc(b) - calc(a - 1) << \"\\n\";",
        "    }",
        "}",
        "",
        "int main() {",
        "    ios_base::sync_with_stdio(0);",
        "    cin.tie(0); cout.tie(0);",
        "    // freopen(\"input.txt\", \"r\", stdin);",
        "    // freopen(\"output.txt\", \"w\", stdout);",
        "",
        "    int tc; tc = 1;",
        "    for (int t = 1; t <= tc; t++) {",
        "        // cout << \"Case #\" << t  << \": \";",
        "        solve();",
        "    }",
        "}"
      }),
      i(0),  -- Final cursor position
    }),

    -- [Dynamic Programming] Elevator Rides.cpp: Find the minimum of elevator rides to move n people knowing everyone's weight and the elevator's lim
    s("elevator_rides", {
      t({
        "#include <bits/stdc++.h>",
        "",
        "using namespace std;",
        "",
        "#define ar array",
        "#define ll long long",
        "",
        "const int MAX_N = 1e5 + 1;",
        "const int MOD = 1e9 + 7;",
        "const int INF = 1e9;",
        "const ll LINF = 1e18;",
        "",
        "",
        "",
        "void solve() {",
        "    int n, x; cin >> n >> x;",
        "    int weight[n]; ",
        "    for (int i = 0; i < n; i++) cin >> weight[i];",
        "",
        "    ar<int,2> dp[1 << n];",
        "    // dp[i][0] = the minimum number of rides for bitmask i",
        "    // dp[i][1] = the minimum weight of the last ride for bitmask i",
        "    dp[0] = {0, 0};",
        "    for (int i = 1; i < (1 << n); i++) {",
        "        // upper bound is n + 1 rides",
        "        dp[i] = {n + 1, 0};",
        "        for (int j = 0; j < n; j++) {",
        "            if (i & (1 << j)) {",
        "                auto cur = dp[i ^ (1 << j)];",
        "                if (cur[1] + weight[j] <= x) { // add j to the current ride",
        "                    cur[1] += weight[j];",
        "                }",
        "                else { // reserves a new ride for j",
        "                    cur[0]++;",
        "                    cur[1] = weight[j];",
        "                }",
        "                dp[i] = min(dp[i], cur);",
        "            }",
        "        }",
        "    }",
        "    // if dp[i].second > 0, then the answer is dp[i].first + 1",
        "    cout << dp[(1 << n) - 1][0] + (dp[(1 << n) - 1][1] > 0);",
        "}",
        "",
        "int main() {",
        "    ios_base::sync_with_stdio(0);",
        "    cin.tie(0); cout.tie(0);",
        "    // freopen(\"input.txt\", \"r\", stdin);",
        "    // freopen(\"output.txt\", \"w\", stdout);",
        "",
        "    int tc; tc = 1;",
        "    for (int t = 1; t <= tc; t++) {",
        "        // cout << \"Case #\" << t  << \": \";",
        "        solve();",
        "    }",
        "}"
      }),
      i(0),  -- Final cursor position
    }),

