    -- [Dynamic Programming] Matrix Chain.cpp: Similar to "Cutting Sticks", a variation of Matrix Chain Multiplication DP Problem
    s("matrix_chain", {
      t({
        "#include <bits/stdc++.h>",
        "",
        "using namespace std;",
        "",
        "#define ar array",
        "#define ll long long",
        "",
