    -- [Dynamic Programming] Traveling Salesman Problem (TSP).cpp: Given n cities/nodes, find a minimum weight Hamiltonian Cycle/Tour
    s("tsp_tsp", {
      t({
        "#include <bits/stdc++.h>",
        "",
        "using namespace std;",
        "",
        "#define ar array",
        "#define ll long long",
        "",
        "const int MAX_N = 11;",
        "const int MOD = 1e9 + 7;",
        "const int INF = 1e9;",
        "const ll LINF = 1e18;",
        "",
        "int n, x[MAX_N], y[MAX_N], adj[MAX_N][MAX_N], dp[1 << MAX_N][MAX_N];",
        "",
        "int tsp(int mask, int u) {",
        "    if (mask == (1 << n) - 1) return adj[u][0]; // finish all nodes (bitmask == 11...11)",
        "    if (dp[mask][u] != -1) return dp[mask][u];",
        "",
        "    int ans = INF;",
        "    // Visit all the unvisited nodes and take the best route",
        "    for (int v = 0; v < n; v++) {",
        "        if (!(mask & (1 << v))) { // this node is unvisited",
        "            int cur = adj[u][v] + tsp(mask | (1 << v), v);",
        "            ans = min(ans, cur);",
        "        }",
        "    }",
        "    return dp[mask][u] = ans;",
        "}",
        "",
        "void solve() {",
        "    int xs, ys; cin >> xs >> ys; // not important",
        "    cin >> x[0] >> y[0] >> n; n++;",
        "    for (int i = 1; i < n; i++) cin >> x[i] >> y[i];",
        "    for (int i = 0; i < n; i++) ",
        "        for (int j = i; j < n; j++)",
        "            adj[i][j] = adj[j][i] = abs(x[i] - x[j]) + abs(y[i] - y[j]);",
        "    memset(dp, -1, sizeof dp);",
        "    // start from node 0 (bitmask = 00...01)",
        "    cout << \"The shortest path has length \" << tsp(1, 0) << \"\\n\";",
        "}",
        "",
        "int main() {",
        "    ios_base::sync_with_stdio(0);",
        "    cin.tie(0); cout.tie(0);",
        "    // freopen(\"input.txt\", \"r\", stdin);",
        "    // freopen(\"output.txt\", \"w\", stdout);",
        "",
        "    int tc; cin >> tc;",
        "    for (int t = 1; t <= tc; t++) {",
        "        // cout << \"Case #\" << t  << \": \";",
        "        solve();",
        "    }",
        "}"
      }),
      i(0),  -- Final cursor position
    }),

    -- [Dynamic Programming] Weighted Job Scheduling.cpp: Given a list of jobs with start time, end time, and profit, find the maximum profit
    s("wjs", {
      t({
        "#include <bits/stdc++.h>",
        "",
        "using namespace std;",
        "",
        "#define ar array",
        "#define ll long long",
        "",
        "const int MAX_N = 1e5 + 1;",
        "const int MOD = 1e9 + 7;",
        "const int INF = 1e9;",
        "const ll LINF = 1e18;",
        "",
        "",
        "",
        "void solve() {",
        "    int n; cin >> n;",
        "    ar<ll,3> arr[n];",
        "    for (int i = 0; i < n; i++) cin >> arr[i][1] >> arr[i][0] >> arr[i][2];",
        "    sort(arr, arr + n); // sort based on end time",
        "    ll dp[n];",
        "    dp[0] = arr[0][2];",
        "    for (int i = 1; i < n; i++) {",
        "        int k = lower_bound(arr, arr + n, ar<ll,3>{arr[i][1], 0, 0}) - arr - 1;",
        "        if (k >= 0)",
        "            dp[i] = max(dp[i - 1], dp[k] + arr[i][2]);",
        "        else",
        "            dp[i] = max(dp[i - 1], arr[i][2]);",
