    -- [Lowest Common Ancestor] LCA (Binary Lifting).cpp: Time complexity: O(nlogn) build, O(logn) per query
    s("binlift_bina", {
      t({
        "#include <bits/stdc++.h>",
        " ",
        "using namespace std;",
        " ",
        "#define ar array",
        "#define ll long long",
        " ",
        "const int MAX_N = 2e5 + 1;",
        "const ll MOD = 1e9 + 7;",
        "const ll INF = 1e9;",
        " ",
        "const int MAX_L = 20;",
        " ",
        "int n, q, par[MAX_N][MAX_L], dep[MAX_N];",
        "vector<int> adj[MAX_N];",
        " ",
        "void dfs(int u, int p = 0) {",
        "    par[u][0] = p;",
        "    for (int i = 1; i < MAX_L; i++) ",
        "        par[u][i] = par[par[u][i - 1]][i - 1];",
        "    for (int v : adj[u]) {",
        "        if (v == p) continue;",
        "        dep[v] = dep[u] + 1;",
        "        dfs(v, u);",
        "    }",
        "}",
        " ",
        "int ancestor(int u, int k) {",
        "    for (int i = 0; i < MAX_L; i++) ",
        "        if (k & (1 << i)) ",
        "            u = par[u][i];",
        "    return u;",
        "}",
        " ",
        "int lca(int u, int v) {",
        "    if (dep[u] < dep[v]) swap(u, v);",
        "    u = ancestor(u, dep[u] - dep[v]);",
        "    if (u == v) return u;",
        "    for (int i = MAX_L - 1; i >= 0; i--)",
        "        if (par[u][i] != par[v][i])",
        "            u = par[u][i], v = par[v][i];",
        "    return par[u][0];",
        "}",
        " ",
        "void solve() {",
        "    cin >> n >> q;",
        "    for (int v = 2; v <= n; v++) {",
        "        int u; cin >> u;",
        "        adj[u].push_back(v);",
        "        adj[v].push_back(u);",
        "    }",
        "    dfs(1);",
        "    while (q--) {",
        "        int u, v; cin >> u >> v;",
        "        cout << lca(u, v) << \"\\n\";",
        "    }",
        "}",
        " ",
        "int main() {",
        "    ios_base::sync_with_stdio(0);",
        "    cin.tie(0); cout.tie(0);",
        "    int tc = 1;",
        "    // cin >> tc;",
        "    for (int t = 1; t <= tc; t++) {",
        "        // cout << \"Case #\" << t << \": \";",
        "        solve();",
        "    }",
        "}"
      }),
      i(0),  -- Final cursor position
    }),

    -- [Lowest Common Ancestor] LCA (RMQ).cpp: Convert the Lowest Common Ancestor (LCA) problem into the Range Minimum Query (RMQ) Problem
    s("lca_rmq", {
      t({
        "#include <bits/stdc++.h>",
        "",
        "using namespace std;",
        "",
        "#define ar array",
        "#define ll long long",
        "",
        "const int MAX_N = 2e5 + 1;",
        "const int MOD = 1e9 + 7;",
        "const int INF = 1e9;",
        "const ll LINF = 1e18;",
        "",
        "const int MAX_L = 30;",
        "",
        "int n, q, idx;",
        "int dep[2 * MAX_N], euler[2 * MAX_N], first[MAX_N], lg[2 * MAX_N];",
        "ar<int,2> dp[2 * MAX_N][MAX_L]; // need to store both the indices and the min value",
        "vector<int> adj[MAX_N];",
        "",
        "void dfs(int u, int p = 0, int h = 0) {",
        "    euler[++idx] = u;",
        "    dep[idx] = h;",
        "    first[u] = idx;",
        "    for (int v : adj[u]) {",
        "        if (v != p) {",
        "            dfs(v, u, h + 1);",
        "            euler[++idx] = u;",
        "            dep[idx] = h;",
        "        }",
        "    }",
        "}",
        "",
        "void build_lg_table() {",
        "    lg[1] = 0;",
        "    for (int i = 2; i <= 2 * n; i++) ",
        "        lg[i] = lg[i / 2] + 1;",
        "}",
        " ",
        "void build_sparse_table() {",
        "    for (int i = 1; i <= 2 * n; i++)",
        "        dp[i][0] = {dep[i], euler[i]};",
        "    for (int j = 1; j < MAX_L; j++)",
        "        for (int i = 1; i + (1 << j) <= 2 * (n + 1); i++)",
        "            dp[i][j] = min(dp[i][j - 1], dp[i + (1 << (j - 1))][j - 1]);",
        "}",
        "",
        "int min_query(int l, int r) { ",
        "    int k = lg[r - l + 1];",
        "    return min(dp[l][k], dp[r - (1 << k) + 1][k])[1]; // return the index with min value",
        "}",
        "",
        "int lca(int u, int v) {",
        "    int l = first[u], r = first[v];",
        "    if (l > r) swap(l, r);",
        "    return min_query(l, r);",
        "}",
        " ",
        "void solve() {",
        "    cin >> n >> q;",
        "    for (int v = 2; v <= n; v++) {",
        "        int u; cin >> u;",
        "        adj[u].push_back(v);",
        "    }",
        "    dfs(1);",
        "    build_lg_table();",
        "    build_sparse_table();",
        "    while (q--) {",
        "        int a, b; cin >> a >> b;",
        "        cout << lca(a, b) << \"\\n\";",
        "    }",
        "    cout << \"\\n\";",
        "}",
        "",
        "int main() {",
        "    ios_base::sync_with_stdio(0);",
        "    cin.tie(0); cout.tie(0);",
        "    // freopen(\"input.txt\", \"r\", stdin);",
        "    // freopen(\"output.txt\", \"w\", stdout);",
        "",
        "    int tc; tc = 1;",
        "    for (int t = 1; t <= tc; t++) {",
        "        // cout << \"Case #\" << t  << \": \";",
        "        solve();",
        "    }",
        "}"
      }),
      i(0),  -- Final cursor position
    }),

    -- [Max Flow] Dinic.cpp: Maximum Flow (Dinic Algorithm)
    s("maxflow", {
      t({
        "#include <bits/stdc++.h>",
        "",
        "using namespace std;",
        "",
        "#define ar array",
        "#define ll long long",
        "",
        "const int MAX_N = 1e5 + 5;",
        "const ll MOD = 1e9 + 7;",
        "const ll INF = 1e18;",
        "",
        "struct max_flow_graph {",
        "    struct edge {",
        "        int u, v, cap, flow;",
        "    };",
        "    int n; ",
        "    vector<edge> el; ",
        "    vector<vector<int>> adj;",
        "    vector<int> dist, par;",
        "    max_flow_graph(int n) : n(n), adj(n) {}",
        "    void add_edge(int u, int v, int w) {",
        "        adj[u].push_back(el.size());",
        "        el.push_back({u, v, w, 0});",
        "        adj[v].push_back(el.size());",
        "        el.push_back({v, u, 0, 0}); ",
        "    }",
        "    int send_one_flow(int s, int e) {",
        "        int nf = INF;",
        "        for (int u = e; u != s; u = el[par[u]].u) {",
        "            nf = min(nf, el[par[u]].cap - el[par[u]].flow);",
        "        }",
        "        for (int u = e; u != s; u = el[par[u]].u) {",
        "            el[par[u]].flow += nf;",
        "            el[par[u]^1].flow -= nf;",
        "        }",
        "        return nf;",
        "    }",
        "    bool bfs(int s, int e) {",
        "        dist.assign(n, INF);",
        "        par.assign(n, 0);",
        "        queue<int> q;",
        "        q.push(s); dist[s] = 0;",
        "        while (q.size()) {",
        "            int u = q.front(); q.pop();",
        "            if (u == e) break;",
        "            for (int idx : adj[u]) {",
        "                if (el[idx].cap > el[idx].flow && dist[el[idx].v] > dist[el[idx].u] + 1) {",
        "                    dist[el[idx].v] = dist[el[idx].u] + 1;",
        "                    par[el[idx].v] = idx;",
        "                    q.push(el[idx].v);",
        "                }",
        "            }",
        "        }",
        "        return dist[e] < INF;",
        "    }",
        "    int dfs(int s, int e, int f = INF) {",
        "        if (s == e || f == 0) return f;",
        "        for (int idx : adj[s]) {",
        "            if (dist[el[idx].v] != dist[s] + 1) continue;",
        "            if (int nf = dfs(el[idx].v, e, min(f, el[idx].cap - el[idx].flow))) {",
        "                el[idx].flow += nf;",
        "                el[idx^1].flow -= nf;",
        "                return nf;",
        "            }",
        "        }",
        "        return 0;",
        "    }",
        "    ll dinic(int s, int e) {",
        "        ll mf = 0;",
        "        while (bfs(s, e)) {",
        "            while (int nf = dfs(s, e)) mf += nf;",
        "        }",
        "        return mf;",
        "    }",
        "};",
        "",
        "void solve() {",
        "    int n, m; cin >> n >> m;",
        "    max_flow_graph adj(n);",
        "    for (int i = 0; i < m; i++) {",
        "        int u, v, w; cin >> u >> v >> w; u--; v--;",
        "        adj.add_edge(u, v, w);",
        "    }",
        "    cout << adj.dinic(0, n - 1) << \"\\n\";",
        "}",
        "",
        "int main() {",
        "    ios_base::sync_with_stdio(0);",
        "    cin.tie(0); cout.tie(0);",
        "    int tc = 1;",
        "    // cin >> tc;",
        "    for (int t = 1; t <= tc; t++) {",
        "        // cout << \"Case #\" << t << \": \";",
        "        solve();",
        "    }",
        "}"
      }),
      i(0),  -- Final cursor position
    }),

    -- [Max Flow] Edmonds_Karp.cpp: Maximum Flow (Dinic Algorithm)
    s("maxflow_mf1", {
      t({
        "#include <bits/stdc++.h>",
        "",
        "using namespace std;",
        "",
        "#define ar array",
        "#define ll long long",
        "",
        "const int MAX_N = 1e5 + 5;",
        "const ll MOD = 1e9 + 7;",
        "const ll INF = 1e18;",
        "",
        "struct max_flow_graph {",
        "    struct edge {",
        "        int u, v, cap, flow;",
        "    };",
        "    int n; ",
        "    vector<edge> el; ",
        "    vector<vector<int>> adj;",
        "    vector<int> dist, par;",
        "    max_flow_graph(int n) : n(n), adj(n) {}",
        "    void add_edge(int u, int v, int w) {",
        "        adj[u].push_back(el.size());",
        "        el.push_back({u, v, w, 0});",
        "        adj[v].push_back(el.size());",
        "        el.push_back({v, u, 0, 0}); ",
        "    }",
        "    int send_one_flow(int s, int e) {",
        "        int nf = INF;",
        "        for (int u = e; u != s; u = el[par[u]].u) {",
        "            nf = min(nf, el[par[u]].cap - el[par[u]].flow);",
        "        }",
        "        for (int u = e; u != s; u = el[par[u]].u) {",
        "            el[par[u]].flow += nf;",
        "            el[par[u]^1].flow -= nf;",
        "        }",
        "        return nf;",
        "    }",
        "    bool bfs(int s, int e) {",
        "        dist.assign(n, INF);",
        "        par.assign(n, 0);",
        "        queue<int> q;",
        "        q.push(s); dist[s] = 0;",
        "        while (q.size()) {",
        "            int u = q.front(); q.pop();",
        "            if (u == e) break;",
        "            for (int idx : adj[u]) {",
        "                if (el[idx].cap > el[idx].flow && dist[el[idx].v] > dist[el[idx].u] + 1) {",
        "                    dist[el[idx].v] = dist[el[idx].u] + 1;",
        "                    par[el[idx].v] = idx;",
        "                    q.push(el[idx].v);",
        "                }",
        "            }",
        "        }",
        "        return dist[e] < INF;",
        "    }",
        "    ll edmonds_karp(int s, int e) {",
        "        ll mf = 0;",
        "        while (bfs(s, e)) mf += send_one_flow(s, e);",
        "        return mf;",
        "    }",
        "};",
        "",
        "void solve() {",
        "    int n, m; cin >> n >> m;",
        "    max_flow_graph adj(n);",
        "    for (int i = 0; i < m; i++) {",
        "        int u, v, w; cin >> u >> v >> w; u--; v--;",
        "        adj.add_edge(u, v, w);",
        "    }",
        "    cout << adj.edmonds_karp(0, n - 1) << \"\\n\";",
        "}",
        "",
        "int main() {",
        "    ios_base::sync_with_stdio(0);",
        "    cin.tie(0); cout.tie(0);",
        "    int tc = 1;",
        "    // cin >> tc;",
        "    for (int t = 1; t <= tc; t++) {",
        "        // cout << \"Case #\" << t << \": \";",
        "        solve();",
        "    }",
        "}"
      }),
      i(0),  -- Final cursor position
    }),

    -- [Minimum Spanning Tree] Kruskal.cpp: Need to use edge list for Kruskal
    s("kruskal", {
      t({
        "#include <bits/stdc++.h>",
        "",
        "using namespace std;",
        "",
        "#define ar array",
        "#define ll long long",
        "",
        "const int MAX_N = 1e5 + 1;",
        "const int MOD = 1e9 + 7;",
        "const int INF = 1e9;",
        "const ll LINF = 1e18;",
        "",
        "int n, m, par[MAX_N];",
        "vector<array<int,3>> edges;",
        " ",
        "int find(int u) {",
        "    return u == par[u] ? u : par[u] = find(par[u]);",
        "}",
        " ",
        "void unite(int u, int v) {",
        "    par[find(u)] = find(v);",
        "}",
        "",
        "void kruskal() {",
        "    sort(edges.begin(), edges.end());",
        "    for (int i = 1; i <= n; i++) par[i] = i;",
        "",
        "    ll cnt = 0, cost = 0;",
        "    for (auto [w, u, v] : edges) {",
        "        u = find(u), v = find(v);",
        "        if (u != v) {",
        "            par[u] = v;",
        "            cost += w;",
        "            cnt++;",
        "        }",
        "    }",
        "    if (cnt == n - 1) cout << cost << \"\\n\";",
        "    else cout << \"IMPOSSIBLE\\n\";",
        "}",
        "",
        "void solve() {",
        "    cin >> n >> m;",
        "    for (int i = 0; i < m; i++) {",
        "        int u, v, w; cin >> u >> v >> w;",
        "        edges.push_back({w, u, v});",
        "    }",
        "    kruskal();",
        "}",
        " ",
        "int main() {",
        "    ios_base::sync_with_stdio(0);",
        "    cin.tie(0); cout.tie(0);",
        "    // freopen(\"input.txt\", \"r\", stdin);",
        "    // freopen(\"output.txt\", \"w\", stdout);",
        " ",
        "    int tc; tc = 1;",
        "    for (int t = 1; t <= tc; t++) {",
        "        // cout << \"Case #\" << t  << \": \";",
        "        solve();",
        "    }",
        "}"
      }),
      i(0),  -- Final cursor position
    }),

    -- [Minimum Spanning Tree] Prim.cpp: Prim Agorithm is similar to Dijkstra
    s("prim", {
      t({
        "#include <bits/stdc++.h>",
        "",
        "using namespace std;",
        "",
        "#define ar array",
        "#define ll long long",
        "",
        "const int MAX_N = 1e5 + 1;",
        "const int MOD = 1e9 + 7;",
        "const int INF = 1e9;",
        "const ll LINF = 1e18;",
        "",
        "int n, m, visited[MAX_N];",
        "vector<ar<int,2>> adj[MAX_N];",
        "",
        "void prim(int s = 1) {",
        "    ll cost = 0;",
        "    priority_queue<ar<ll,2>, vector<ar<ll,2>>, greater<ar<ll,2>>> pq;",
        "    visited[s] = 1; ",
        "    for (auto [u, d] : adj[s]) ",
        "        if (!visited[u]) ",
        "            pq.push({d, u});",
        "    while (pq.size()) {",
        "        auto [d, u] = pq.top(); pq.pop();",
        "        if (!visited[u]) {",
        "            cost += d;",
        "            visited[u] = 1;",
        "            for (auto [v, w] : adj[u]) ",
        "                if (!visited[v]) ",
        "                    pq.push({w, v});",
        "        }",
        "    } ",
        "    for (int i = 1; i <= n; i++) {",
        "        if (!visited[i]) {",
        "            cout << \"IMPOSSIBLE\\n\";",
        "            exit(0);",
        "        }",
        "    }",
        "    cout << cost << \"\\n\";",
        "}",
        "",
        "void solve() {",
        "    cin >> n >> m;    ",
        "    for(int i = 0; i < m; i++) {",
        "        int u, v, w; cin >> u >> v >> w;",
        "        adj[u].push_back({v, w}); ",
        "        adj[v].push_back({u, w});",
        "    }",
        "    prim();",
        "}",
        "",
        "int main() {",
        "    ios_base::sync_with_stdio(0);",
        "    cin.tie(0); cout.tie(0);",
        "    // freopen(\"input.txt\", \"r\", stdin);",
        "    // freopen(\"output.txt\", \"w\", stdout);",
        "",
        "    int tc; tc = 1;",
        "    for (int t = 1; t <= tc; t++) {",
        "        // cout << \"Case #\" << t  << \": \";",
        "        solve();",
        "    }",
        "}"
      }),
      i(0),  -- Final cursor position
    }),

