    -- [Shortest Paths] Floyd_Warshall.cpp: Find all pair shortest paths
    s("floyd_warshall", {
      t({
        "#include <bits/stdc++.h>",
        "",
        "using namespace std;",
        "",
        "#define ar array",
        "#define ll long long",
        "",
        "const int MAX_N = 500 + 1;",
        "const int MOD = 1e9 + 7;",
        "const int INF = 1e9;",
        "const ll LINF = 1e15;",
        "",
        "int n, m, q;",
        "ll dist[MAX_N][MAX_N];",
        "",
        "void floyd_warshall() { // 4 lines",
        "    for (int k = 1; k <= n; k++)",
        "        for (int i = 1; i <= n; i++) ",
        "            for (int j = 1; j <= n; j++)",
        "                dist[i][j] = min(dist[i][j], dist[i][k] + dist[k][j]);",
        "}",
        " ",
        "void solve() {",
        "    cin >> n >> m >> q;",
        "    for (int i = 1; i <= n; i++)",
        "        for (int j = 1; j <= n; j++)",
        "            dist[i][j] = (i == j) ? 0 : LINF;",
        "    for (int i = 0; i < m; i++) {",
        "        int u, v, w; cin >> u >> v >> w;",
        "        dist[u][v] = dist[v][u] = min(dist[u][v], (ll)w); ",
        "    }",
        "    floyd_warshall();",
        "    while (q--) {",
        "        int u, v; cin >> u >> v;",
        "        cout << (dist[u][v] < LINF ? dist[u][v] : -1) << \"\\n\";",
        "    }",
        "}",
        " ",
        "int main() {",
        "    ios_base::sync_with_stdio(0);",
        "    cin.tie(0); cout.tie(0);",
        "    // freopen(\"input.txt\", \"r\", stdin);",
        "    // freopen(\"output.txt\", \"w\", stdout);",
        " ",
        "    int tc; tc = 1;",
        "    for (int t = 1; t <= tc; t++) {",
        "        // cout << \"Case #\" << t  << \": \";",
        "        solve();",
        "    }",
        "}"
      }),
      i(0),  -- Final cursor position
    }),

    -- [Strongly Connected Components (SSCs)] Bridges&ArticulationPoints.cpp: Given an undirected graph, find all bridges and articulation points
    s("scc", {
      t({
        "#include <bits/stdc++.h>",
        "",
        "using namespace std;",
        "",
        "#define ar array",
        "#define ll long long",
        "",
        "const int MAX_N = 1e5 + 1;",
        "const int MOD = 1e9 + 7;",
        "const int INF = 1e9;",
        "const ll LINF = 1e18;",
        "",
        "// dfs_num[u] stores the iteration counter when DFS visits node u for the 1st time",
        "// dfs_low[u] stores the lowest dfs_num reachable from the current DFS spanning subtree of node u",
        "// dfs_low[u] can only be made smaller if there is a back edge to form a cycle and v is currently visited",
        "",
        "int n, m, dfsCounter;",
        "int dfs_num[MAX_N], dfs_low[MAX_N], visited[MAX_N];",
        "vector<int> adj[MAX_N];",
        "",
        "void dfs(int u, int p = -1) {",
        "    dfs_num[u] = dfs_low[u] = dfsCounter++;",
        "    visited[u] = 1;",
        "    int num_child = 0;",
        "    for (int v : adj[u]) {",
        "        if (v == p) continue; ",
        "        // back edge",
        "        if (visited[v]) dfs_low[u] = min(dfs_low[u], dfs_num[v]); ",
        "        // tree edge",
        "        else { ",
        "            dfs(v, u);",
        "            dfs_low[u] = min(dfs_low[u], dfs_low[v]);  ",
        "            num_child++;",
        "            if (dfs_low[v] > dfs_num[u]) ",
        "                cout << \"Edge \" << u << \"-\" << v << \" is a bridge\\n\";",
        "            if (dfs_low[v] >= dfs_num[u] && p != -1)",
        "                cout << \"Node \" << u << \" is an articulation point\\n\";",
        "        }",
        "    }",
        "    // special case: the root node is an articulation point if it has more than 1 child",
        "    if (p == -1 && num_child > 1) ",
        "        cout << \"Node \" << u << \" is an articulation point\\n\";",
        "}",
        "",
        "void solve() {",
        "    cin >> n >> m;",
        "    for (int i = 0; i < m; i++) {",
        "        int u, v; cin >> u >> v;",
