    -- [Topological Sort] Topological Sort (in_deg).cpp: Greedily take all nodes with in_deg == 0 and push them into the topological ordering, then decrease 
    s("toposort_in_d", {
      t({
        "#include <bits/stdc++.h>",
        "",
        "using namespace std;",
        "",
        "#define ar array",
        "#define ll long long",
        "",
        "const int MAX_N = 1e5 + 1;",
        "const int MOD = 1e9 + 7;",
        "const int INF = 1e9;",
        "const ll LINF = 1e18;",
        "",
        "int n, m, visited[MAX_N], in_deg[MAX_N];",
        "vector<int> adj[MAX_N], topo;",
        " ",
        "void build_topo() {",
        "    for (int u = 1; u <= n; u++) ",
        "        for (int v : adj[u]) ",
        "            in_deg[v]++;",
        "    queue<int> q;",
        "    for (int u = 1; u <= n; u++) ",
        "        if (in_deg[u] == 0) ",
        "            q.push(u);",
        "    while (q.size()) {",
        "        int u = q.front(); q.pop();",
        "        topo.push_back(u);",
        "        for (int v : adj[u]) {",
        "            in_deg[v]--;",
        "            if (in_deg[v] == 0) q.push(v);",
        "        }",
        "    }",
        "    // detect cycle",
        "    for (int i = 1; i <= n; i++) { ",
        "        if (in_deg[i]) {",
        "            cout << \"IMPOSSIBLE\\n\";",
        "            exit(0);",
        "        }",
        "    }",
        "}",
        "",
        "void solve() {",
        "    cin >> n >> m;",
        "    for (int i = 0; i < m; i++) {",
        "        int u, v; cin >> u >> v;",
        "        adj[u].push_back(v);",
        "    }",
        "    build_topo();",
        "    for (int x : topo) cout << x << \" \";",
        "    cout << \"\\n\";",
        "}",
        "",
        "int main() {",
        "    ios_base::sync_with_stdio(0);",
        "    cin.tie(0); cout.tie(0);",
        "    // freopen(\"input.txt\", \"r\", stdin);",
        "    // freopen(\"output.txt\", \"w\", stdout);",
        "",
        "    int tc; tc = 1;",
        "    for (int t = 1; t <= tc; t++) {",
        "        // cout << \"Case #\" << t  << \": \";",
        "        solve();",
        "    }",
        "}"
      }),
      i(0),  -- Final cursor position
    }),

    -- [Mathematics] Binomial Coefficients.cpp: Quick calculation of nCk
    s("binomial_coefficients", {
      t({
        "#include <bits/stdc++.h>",
        " ",
        "using namespace std;",
        " ",
        "#define ar array",
        "#define ll long long",
        " ",
        "const int MAX_N = 1e5 + 5;",
        "const ll MOD = 1e9 + 7;",
        "const ll INF = 1e9;",
        "",
        "ll qexp(ll a, ll b, ll m) {",
        "    ll res = 1;",
        "    while (b) {",
        "        if (b % 2) res = res * a % m;",
        "        a = a * a % m;",
        "        b /= 2;",
        "    }",
        "    return res;",
        "}",
        "",
        "vector<ll> fact, invf;",
        "",
        "void precompute(int n) {",
        "    fact.assign(n + 1, 1); ",
        "    for (int i = 1; i <= n; i++) fact[i] = fact[i - 1] * i % MOD;",
        "    invf.assign(n + 1, 1);",
        "    invf[n] = qexp(fact[n], MOD - 2, MOD);",
        "    for (int i = n - 1; i > 0; i--) invf[i] = invf[i + 1] * (i + 1) % MOD;",
        "}",
        "",
        "ll nCk(int n, int k) {",
        "    if (k < 0 || k > n) return 0;",
        "    return fact[n] * invf[k] % MOD * invf[n - k] % MOD;",
        "    // return fact[n] * qexp(fact[k], MOD - 2, MOD) % MOD * qexp(fact[n - k], MOD - 2, MOD) % MOD;",
        "}",
        "",
        "// A trick to calculate large factorial without overflowing is to take log at every step when precompute and take exponential when calculating",
        "// Don't need invf[] now because it is the same as negative log of fact",
        "vector<double> log_fact;",
        "void precompute_log(int n) {",
        "    log_fact.assign(n + 1, 0.0);",
        "    log_fact[0] = 0.0; ",
        "    for (int i = 1; i <= n; i++) log_fact[i] = log_fact[i - 1] + log(i); ",
        "}",
        "",
        "ll log_nCk(int n, int k) { ",
        "    if (k < 0 || k > n) return 0;",
        "    return exp(log_fact[n] - log_fact[n - k] - log_fact[k]); ",
        "}",
        "",
        "void solve() {",
        "    int n, k; cin >> n >> k;",
        "    cout << nCk(n, k) << \"\\n\";",
        "}",
        "",
        "int main() {",
        "    ios_base::sync_with_stdio(0);",
        "    cin.tie(0); cout.tie(0);",
        "    precompute(1e6);",
        "    int tc = 1;",
        "    cin >> tc;",
        "    for (int t = 1; t <= tc; t++) {",
        "        // cout << \"Case #\" << t << \": \";",
        "        solve();",
        "    }",
        "}"
      }),
      i(0),  -- Final cursor position
    }),

    -- [Mathematics] Fibonacci.cpp: Find the n-th Fibonacci number using matrix multiplication and binary exponentiation
    s("fibonacci", {
      t({
        "#include <bits/stdc++.h>",
        "",
        "using namespace std;",
        "",
        "#define ar array",
        "#define ll long long",
        "",
        "const int MAX_N = 1e5 + 5;",
        "const ll MOD = 1e9 + 7;",
        "const ll INF = 1e9;",
        "",
        "template<int _MOD> struct Modular {",
        "    int v; explicit operator int() const { return v; } // explicit -> don't silently convert to int",
        "    Modular() { v = 0; }",
        "    Modular(ll _v) { v = int((-_MOD < _v && _v < _MOD) ? _v : _v % _MOD); if (v < 0) v += _MOD; }",
        "    friend std::ostream& operator<<(std::ostream& out, const Modular& n) { return out << int(n); }",
        "    friend std::istream& operator>>(std::istream& in, Modular& n) { ll v_; in >> v_; n = Modular(v_); return in; }",
        "",
        "    friend bool operator==(const Modular& a, const Modular& b) { return a.v == b.v; }",
        "    friend bool operator!=(const Modular& a, const Modular& b) { return a.v != b.v; }",
        "    friend bool operator<(const Modular& a, const Modular& b) { return a.v < b.v; }",
        "",
        "    Modular& operator+=(const Modular& m) { if ((v += m.v) >= _MOD) v -= _MOD; return *this; }",
        "    Modular& operator-=(const Modular& m) { if ((v -= m.v) < 0) v += _MOD; return *this; }",
        "    Modular& operator*=(const Modular& m) { v = int((ll)v*m.v%_MOD); return *this; }",
        "    Modular& operator/=(const Modular& m) { return (*this) *= inv(m); }",
        "    Modular operator-() const { return Modular(-v); }",
        "    Modular& operator++() { return *this += 1; }",
        "    Modular& operator--() { return *this -= 1; }",
        "    friend Modular pow(Modular a, ll p) {",
        "        Modular ans = 1; assert(p >= 0);",
        "        for (; p; p /= 2, a *= a) if (p&1) ans *= a;",
        "        return ans; ",
        "    }",
        "    friend Modular inv(const Modular& a) { assert(a.v != 0); return pow(a,_MOD-2); }",
        "",
        "    friend Modular operator+(Modular a, const Modular& b) { return a += b; }",
        "    friend Modular operator-(Modular a, const Modular& b) { return a -= b; }",
        "    friend Modular operator*(Modular a, const Modular& b) { return a *= b; }",
        "    friend Modular operator/(Modular a, const Modular& b) { return a /= b; }",
        "    friend Modular operator++(Modular& a, int) { Modular r = a; ++a; return r; }friend Modular operator--(Modular& a, int) { Modular r = a; --a; return r; }",
        "};",
        "",
        "template <class T> struct matrix {",
        "    vector<vector<T>> m;",
        "    int r, c;",
        "    matrix() : r(), c() {}",
        "    matrix(int r, int c, T x) : r(r), c(c), m(r, vector<T>(c, x)) {}",
        "    matrix(int n) : matrix(n, n, 0) { // identity matrix",
        "        for (int i = 0; i < n; i++) m[i][i] = 1;",
        "    }",
        "    matrix operator* (matrix<T> b) {",
        "        matrix<T> a = *this;",
        "        assert(a.c == b.r);",
        "        matrix<T> o(a.r, b.c, 0);",
        "        for (int i = 0; i < a.r; i++)",
        "            for (int j = 0; j < b.c; j++)",
        "                for (int k = 0; k < a.c; k++)",
        "                    o.m[i][j] = o.m[i][j] + a.m[i][k] * b.m[k][j];",
        "        return o;",
        "    }",
        "    matrix operator^ (ll b) {",
        "        matrix<T> a = *this;",
        "        assert(a.r == a.c);",
        "        matrix<T> o(a.r);",
        "        while (b) {",
        "            if (b % 2) o = o * a;",
        "            a = a * a;",
        "            b /= 2;",
        "        }",
        "        return o;",
        "    }",
        "    void print() {",
        "        for (int i = 0; i < r; i++) {",
        "            for (int j = 0; j < c; j++) cout << m[i][j] << \" \";",
        "            cout << \"\\n\";",
        "        }",
        "    }",
        "};",
        "",
        "using mint = Modular<MOD>;",
        "",
        "void solve() {",
        "    ll n; cin >> n;",
        "    matrix<mint> A(1, 2, 0); ",
        "    A.m[0][0] = 0; A.m[0][1] = 1;",
        "    matrix<mint> B(2, 2, 0);",
        "    B.m[0][0] = 0; B.m[0][1] = 1;",
        "    B.m[1][0] = 1; B.m[1][1] = 1;",
        "    A = A * (B ^ n);",
        "    cout << A.m[0][0] << \"\\n\";",
        "}",
        "",
        "int main() {",
        "    ios_base::sync_with_stdio(0);",
        "    cin.tie(0); cout.tie(0);",
        "    int tc = 1;",
        "    // cin >> tc;",
        "    for (int t = 1; t <= tc; t++) {",
        "        // cout << \"Case #\" << t << \": \";",
        "        solve();",
        "    }",
        "}"
      }),
      i(0),  -- Final cursor position
    }),

    -- [Mathematics] GCD.cpp: Find the greatest common divisor (GCD) of two integers
    s("gcd", {
      t({
        "#include <bits/stdc++.h>",
        "",
        "using namespace std;",
        "",
        "#define ar array",
        "#define ll long long",
        "",
        "const int MAX_N = 1e5 + 5;",
        "const ll MOD = 1e9 + 7;",
        "const ll INF = 1e9;",
        "",
        "int gcd(int a, int b) {",
        "    return b ? gcd(b, a % b) : a;",
        "}",
        "",
        "// extended version to find x, y such that ax + by = gcd(a, b)",
        "ll gcd(ll a, ll b, ll &x, ll &y) {",
        "    if (b == 0) {x = 1, y = 0; return a;}",
        "    ll x1, y1, d = gcd(b, a % b, x1, y1);",
        "    x = y1;",
        "    y = x1 - y1 * (a / b);",
        "    return d;",
        "}",
        "",
        "// find a solution of a Linear Diophantine Equation",
        "bool lde(ll a, ll b, ll c, ll &x, ll &y) {",
        "    ll d = gcd(abs(a), abs(b), x, y);",
        "    if (c % d) return false; ",
        "    x *= c / d; ",
        "    y *= c / d;",
        "    if (a < 0) x = -x;",
        "    if (b < 0) y = -y;",
        "    return true;",
        "}",
        "",
        "void shift(ll a, ll b, ll &x, ll &y, ll cnt) {",
        "    x += cnt * b;",
        "    y -= cnt * a;",
        "}",
        "",
        "ll inv_mod(ll a, ll m) {",
        "    ll x, y;",
        "    gcd(a, m, x, y);",
        "    return (m + x % m) % m;",
        "}",
        "",
        "// solve ax = b (mod m)",
        "ll lce(ll a, ll b, ll m) {",
        "    ll d = gcd(a, m);",
        "    if (d != 1) {",
        "        if (b % d) return -1;",
        "        a /= d; b /= d; m /= d;",
        "    }",
        "    return b * inv_mod(a, m) % m;",
        "}",
        "",
        "void solve() {",
        "    int a, b; cin >> a >> b;",
        "    cout << gcd(a, b) << \"\\n\";",
