    -- [Mathematics] Sieve Of Eratosthenes.cpp: Generate the all primes <= n
    s("sieve", {
      t({
        "#include <bits/stdc++.h>",
        "",
        "using namespace std;",
        "",
        "#define ar array",
        "#define ll long long",
        "",
        "const int MAX_N = 1e6 + 5;",
        "const ll MOD = 1e9 + 7;",
        "const ll INF = 1e9;",
        "",
        "// vector<int> primes, is_prime, spf;",
        "",
        "// void sieve(int n) {",
        "//     primes.clear();",
        "//     is_prime.assign(n + 1, 1);",
        "//     spf.assign(n + 1, 0);",
        "//     is_prime[0] = is_prime[1] = false;",
        "//     for (ll i = 2; i <= n; i++) {",
        "//         if (is_prime[i]) {",
        "//             primes.push_back(i);",
        "//             spf[i] = i;",
        "//             for (ll j = i * i; j <= n; j += i) {",
        "//                 is_prime[j] = false;",
        "//                 spf[j] = i;",
        "//             }",
        "//         }",
        "//     }",
        "// }",
        "",
        "// Linear sieve including calculating the smallest prime factor (spf), Mobius function, and Euler's totient function",
        "vector<int> primes, is_prime, spf, mobius, phi;",
        "",
        "void sieve(int n) {",
        "    primes.clear();",
        "    is_prime.assign(n + 1, 1);",
        "    spf.assign(n + 1, 0);",
        "    mobius.assign(n + 1, 0);",
        "    phi.assign(n + 1, 0);",
        "    is_prime[0] = is_prime[1] = 0;",
        "    mobius[1] = phi[1] = 1;",
        "    for (ll i = 2; i <= n; i++) {",
        "        if (is_prime[i]) {",
        "            primes.push_back(i);",
        "            spf[i] = i;",
        "            mobius[i] = -1;",
        "            phi[i] = i - 1;",
        "        }",
        "        for (auto p : primes) {",
        "            if (i * p > n || p > spf[i]) break;",
        "            is_prime[i * p] = 0;",
        "            spf[i * p] = p;",
        "            mobius[i * p] = (spf[i] == p) ? 0 : -mobius[i];",
        "            phi[i * p] = (spf[i] == p) ? phi[i] * p : phi[i] * phi[p];",
        "        }",
        "    }",
        "}",
        "",
        "void solve() {",
        "    int n; cin >> n;",
        "    vector<int> cnt(MAX_N);",
        "    while (n--) {",
        "        int x; cin >> x;",
        "        cnt[x]++;",
        "    }",
        "    ll ans = 0;",
        "    for (int i = 1; i < MAX_N; i++) {",
        "        if (!mobius[i]) continue;",
        "        ll tmp = 0;",
        "        for (int j = i; j < MAX_N; j += i) tmp += cnt[j];",
        "        ans += tmp * (tmp - 1) / 2 * mobius[i];",
        "    }",
        "    cout << ans << \"\\n\";",
        "}",
        "",
        "int main() {",
        "    ios_base::sync_with_stdio(0);",
        "    cin.tie(0); cout.tie(0);",
        "    sieve(MAX_N);",
        "    int tc = 1;",
        "    // cin >> tc;",
        "    for (int t = 1; t <= tc; t++) {",
        "        // cout << \"Case #\" << t << \": \";",
        "        solve();",
        "    }",
        "}"
      }),
      i(0),  -- Final cursor position
    }),

    -- [Others] 2SAT.cpp: 2-SAT Problem
    s("2sat", {
      t({
        "#include <bits/stdc++.h>",
        "",
        "using namespace std;",
        "",
        "#define ar array",
        "#define ll long long",
        "",
        "const int MAX_N = 1e5 + 1;",
        "const int MOD = 1e9 + 7;",
        "const int INF = 1e9;",
        "const ll LINF = 1e18;",
        "",
        "int n, m, scc, visited[2 * MAX_N], comp[2 * MAX_N];",
        "char ans[MAX_N];",
        "vector<int> adj[2][2 * MAX_N], dfn;",
        "// adj[0] is the original graph, adj[1] is the transposed graph",
        "",
        "// t = 0 means 1st pass, t = 1 means 2nd pass",
        "void dfs(int u, int t) {",
        "    visited[u] = 1;",
        "    if (t == 1) comp[u] = scc;",
        "    for (int v : adj[t][u]) {",
        "        if (!visited[v]) {",
        "            dfs(v, t);",
        "        }",
        "    }",
        "    if (t == 0) dfn.push_back(u);",
        "}",
        "",
        "void kosaraju() {",
        "    for (int i = 1; i <= 2 * n; i++) {",
        "        if (!visited[i]) {",
        "            dfs(i, 0);",
        "        }",
        "    }",
        "    memset(visited, 0, sizeof visited);",
        "    for (int i = 2 * n; i > 0; i--) {",
        "        if (!visited[dfn[i]]) {",
        "            scc++;",
        "            dfs(dfn[i], 1);",
        "        }",
        "    }",
        "}",
        "",
        "void solve() {",
        "    cin >> m >> n;",
        "    for (int i = 0; i < m; i++) {",
        "        int u1, u2; char c1, c2; cin >> c1 >> u1 >> c2 >> u2;",
        "        u1 *= 2; u2 *= 2; ",
        "        if (c1 == '-') u1 ^= 1;",
        "        if (c2 == '-') u2 ^= 1;",
        "        adj[0][u1 ^ 1].push_back(u2);",
        "        adj[0][u2 ^ 1].push_back(u1);",
        "    }",
        "    for (int i = 1; i <= 2 * n; i++) {",
        "        for (int j : adj[0][i]) {",
        "            adj[1][j].push_back(i);",
        "        }",
        "    }",
        "    kosaraju();",
        "    for (int i = 1; i <= n; i++) {",
        "        if (comp[2 * i] == comp[2 * i + 1]) { ",
        "            cout << \"IMPOSSIBLE\\n\";",
        "            return;",
        "        }",
        "        ans[i] = (comp[2 * i] > comp[2 * i + 1]) ? '+' : '-';",
        "    }",
        "    for (int i = 1; i <= n; i++) cout << ans[i] << \" \";",
        "    cout << \"\\n\";",
        "}",
        " ",
        "int main() {",
        "    ios_base::sync_with_stdio(0);",
        "    cin.tie(0); cout.tie(0);",
        "    //freopen(\"input.txt\", \"r\", stdin);",
        "    //freopen(\"output.txt\", \"w\", stdout);",
        " ",
        "    int tc; tc = 1;",
        "    for (int t = 1; t <= tc; t++) {",
        "        //cout << \"Case #\" << t  << \": \";",
        "        solve();",
        "    }",
        "}"
      }),
      i(0),  -- Final cursor position
    }),

    -- [Others] Closest_3_Points(Divide&Conquer).cpp: Problem link: https://www.codechef.com/LRNDSA04/problems/ACM14KP1
    s("c3p_divide", {
      t({
        "#include <bits/stdc++.h>",
        "",
        "using namespace std;",
        "",
        "#define ar array",
        "#define ll long long",
        "",
        "const int MAX_N = 1e5 + 1;",
        "const int MOD = 1e9 + 7;",
        "const int INF = 1e9;",
        "const ll LINF = 1e18;",
        "",
        "struct pt {",
        "    double x, y;",
        "};",
        "",
        "pt pts[MAX_N];",
        "",
        "bool cmp_x(pt a, pt b) {return a.x < b.x;}",
        "bool cmp_y(pt a, pt b) {return a.y < b.y;}",
        "double dist(pt a, pt b) {return hypot(abs(a.x - b.x), abs(a.y - b.y));}",
        "double perimeter(pt a, pt b, pt c) {return dist(a, b) + dist(b, c) + dist(c, a);}",
        "",
        "double dac(int l, int r) {",
        "    if (r - l <= 1) return INF;",
        "    if (r - l == 2) return perimeter(pts[l], pts[l + 1], pts[l + 2]);",
        "",
        "    int mid = (l + r) / 2;",
        "    double d1 = dac(l, mid), d2 = dac(mid + 1, r);",
        "    double ans = min(d1, d2);",
        "    vector<pt> strip;",
        "    for (int i = l; i <= r; i++) {",
        "        if (abs(pts[i].x - pts[mid].x) < ans) strip.push_back(pts[i]);",
        "    }",
        "    sort(strip.begin(), strip.end(), cmp_y);",
        "    for (int i = 0; i < strip.size(); i++) {",
        "        for (int j = i + 1; j < strip.size() && (strip[j].y - strip[i].y) < ans; j++) {",
        "            for (int k = j + 1; k < strip.size() && (strip[k].y - strip[j].y) < ans; k++) {",
        "                ans = min(ans, perimeter(strip[i], strip[j], strip[k]));",
        "            }",
        "        }",
        "    }",
        "    return ans;",
        "}",
        "",
        "void solve() {",
        "    int n; cin >> n;",
        "    for (int i = 0; i < n; i++) cin >> pts[i].x >> pts[i].y;",
        "    sort(pts, pts + n, cmp_x);",
        "    cout << fixed << setprecision(10) << dac(0, n - 1) << \"\\n\";",
        "}",
        "",
        "int main() {",
        "    ios_base::sync_with_stdio(0);",
        "    cin.tie(0); cout.tie(0);",
        "    // freopen(\"input.txt\", \"r\", stdin);",
        "    // freopen(\"output.txt\", \"w\", stdout);",
        "",
        "    int tc; cin >> tc;",
        "    for (int t = 1; t <= tc; t++) {",
        "        cout << \"Case \" << t  << \": \";",
        "        solve();",
        "    }",
        "}"
      }),
      i(0),  -- Final cursor position
    }),

    -- [Others] Maximum Histogram Area (Monotonic Stack).cpp: Find the largest rectangular area in a histogram
    s("mha_monoto", {
      t({
        "#include <bits/stdc++.h>",
        "",
        "using namespace std;",
        "",
        "#define ar array",
        "#define ll long long",
        "",
        "const int MAX_N = 1e5 + 1;",
        "const int MOD = 1e9 + 7;",
        "const int INF = 1e9;",
        "const ll LINF = 1e18;",
        "",
        "",
        "",
        "void solve() {",
        "    while (true) {",
        "        int n; cin >> n;",
        "        if (!n) return;",
        "        ",
        "        int arr[n], l[n], r[n];",
        "        for (int i = 0; i < n; i++) cin >> arr[i];",
        "        ",
        "        stack<int> st;",
        "        // find left borders",
        "        for (int i = 0; i < n; i++) {",
        "            while (st.size() && arr[st.top()] >= arr[i]) st.pop();",
        "            l[i] = st.size() ? st.top() + 1 : 0;",
        "            st.push(i);",
        "        }",
        "        // clear stack",
        "        while (st.size()) st.pop();",
        "        // find right borders",
        "        for (int i = n - 1; i >= 0; i--) {",
        "            while (st.size() && arr[st.top()] >= arr[i]) st.pop();",
        "            r[i] = st.size() ? st.top() - 1 : n - 1;",
        "            st.push(i);",
        "        }        ",
        "        ",
        "        ll mx = 0;",
        "        for (int i = 0; i < n; i++) {",
        "            ll cur = (ll) arr[i] * (r[i] - l[i] + 1);",
        "            mx = max(mx, cur);",
        "        }",
        "        cout << mx << \"\\n\";",
        "    }",
        "}",
        "",
        "int main() {",
        "    ios_base::sync_with_stdio(0);",
        "    cin.tie(0); cout.tie(0);",
        "    // freopen(\"input.txt\", \"r\", stdin);",
        "    // freopen(\"output.txt\", \"w\", stdout);",
        "",
        "    int tc; tc = 1;",
        "    for (int t = 1; t <= tc; t++) {",
        "        // cout << \"Case #\" << t  << \": \";",
        "        solve();",
        "    }",
        "}"
      }),
      i(0),  -- Final cursor position
    }),

    -- [Others] Median Heap.cpp: Given a stream of n input integers, maintain the median of the current array
    s("median_heap", {
      t({
        "#include <bits/stdc++.h>",
        "",
        "using namespace std;",
        "",
        "#define ar array",
        "#define ll long long",
        "",
        "const int MAX_N = 1e5 + 1;",
        "const int MOD = 1e9 + 7;",
        "const int INF = 1e9;",
        "const ll LINF = 1e18;",
        "",
        "// The current median is stored as lo.top()",
        "",
        "void solve() {",
        "    int n; cin >> n;",
        "    priority_queue<int> lo;",
        "    priority_queue<int, vector<int>, greater<int>> hi;",
        "    vector<int> ans;",
        "    while (n--) {",
        "        string s; cin >> s;",
        "        if (s == \"PUSH\") {",
        "            int x; cin >> x;",
        "            if (hi.empty() || x <= hi.top()) // insert x to the lo heap if possible",
        "                lo.push(x);",
        "            else ",
        "                hi.push(x);",
        "",
        "            // the 2 heaps can become imbalanced, so need to fix it",
        "            if (lo.size() > hi.size() + 1) {",
        "                hi.push(lo.top());",
        "                lo.pop();",
        "            }",
        "            if (lo.size() < hi.size()) {",
        "                lo.push(hi.top());",
        "                hi.pop();",
        "            }",
        "        }",
        "        else { ",
        "            // remove the current median",
        "            lo.pop(); ",
        "            // the 2 heaps can become imbalanced, so need to fix it",
        "            if (lo.size() != hi.size()) {",
        "                lo.push(hi.top());",
        "                hi.pop();",
        "            }",
        "        }",
        "    }",
        "",
        "    // printing the final array in increasing order",
        "    while (!lo.empty()) {",
        "        ans.push_back(lo.top());",
        "        lo.pop();",
        "    }",
        "    // need to reverse as we are popping from a max heap",
        "    reverse(ans.begin(), ans.end()); ",
        "    while (!hi.empty()) {",
        "        ans.push_back(hi.top());",
        "        hi.pop();",
        "    }",
        "    for (int x : ans)",
        "        cout << x << \" \";",
        "}",
        "",
        "int main() {",
        "    ios_base::sync_with_stdio(0);",
        "    cin.tie(0); cout.tie(0);",
        "    // freopen(\"input.txt\", \"r\", stdin);",
        "    // freopen(\"output.txt\", \"w\", stdout);",
        "",
        "    int tc; tc = 1;",
        "    for (int t = 1; t <= tc; t++) {",
        "        // cout << \"Case #\" << t  << \": \";",
        "        solve();",
        "    }",
        "}"
      }),
      i(0),  -- Final cursor position
    }),

