    -- [Others] N Queens.cpp: Count the number of ways to place the queens so that no two queens are attacking each other
    s("n_queens", {
      t({
        "#include <bits/stdc++.h>",
        "",
        "using namespace std;",
        "",
        "#define ar array",
        "#define ll long long",
