        " ",
        "void place(int j) {",
        "    if (j == n) {",
        "        ans++;",
        "        return;",
        "    }",
        "    if (c[j]) place(j + 1);",
        "    else {",
        "        for (int i = 0; i < n; i++) {",
        "            if (!blocked[i][j] && !r[i] && !d1[i + j] && !d2[i - j + n]) {",
        "                blocked[i][j] = r[i] = d1[i + j] = d2[i - j + n] = 1;",
        "                place(j + 1);",
        "                blocked[i][j] = r[i] = d1[i + j] = d2[i - j + n] = 0;",
        "            }",
        "        }",
        "    }",
        "}",
        " ",
        "void solve() {",
        "    for (int i = 0; i < n; i++) {",
        "        for (int j = 0; j < n; j++) {",
        "            char x; cin >> x;",
        "            if (x == '*') blocked[i][j] = 1;",
        "        }",
        "    }",
        "    place(0);",
        "    cout << ans;",
        "}",
