    -- [Others] Offline Dynamic Connectivity.cpp: Use DSU (with rollback) to solve offline dynamic connectivity problems
    s("odc", {
      t({
        "#include <bits/stdc++.h>",
        "",
        "using namespace std;",
        "",
        "#define ar array",
        "#define ll long long",
        "",
        "const int MAX_N = 3e5 + 1;",
        "const int MOD = 1e9 + 7;",
        "const int INF = 1e9;",
        "const ll LINF = 1e18;",
        "",
        "struct DSU {",
        "    int num;",
        "    vector<int> p, sz;",
        "    stack<int> st;",
        "    void init(int n) {",
        "        num = n;",
        "        p.resize(n); for (int i = 0; i < n; i++) p[i] = i;",
        "        sz.assign(n, 1);",
        "    }",
        "    int find(int u) {return u == p[u] ? u : find(p[u]);}",
        "    bool same(int u, int v) {return find(u) == find(v);}",
        "    void merge(int u, int v) {",
        "        if (same(u, v)) return;",
        "        u = find(u), v = find(v);",
        "        if (sz[u] > sz[v]) swap(u, v);",
        "        num--;",
        "        sz[v] += sz[u];",
        "        p[u] = v;",
        "        st.push(u);",
        "    }",
        "    void rollback(int t) {",
        "        while (st.size() > t) {",
        "            int u = st.top(); st.pop();",
        "            num++;",
        "            sz[p[u]] -= sz[u];",
        "            p[u] = u;",
        "        }",
        "    }",
        "};",
        "",
        "int n, m, q, us[MAX_N], vs[MAX_N], other[MAX_N], ans[MAX_N];",
        "vector<ar<int,5>> qs; // {time, type, id, u, v}",
        "map<ar<int,2>,int> mp;",
        "DSU uf;",
        "",
        "void dco(int l, int r) {",
        "    if (l > r) return;",
        "    if (l == r) {",
        "        auto [t, c, id, u, v] = qs[l];",
        "        if (c == 2) ans[id] = uf.same(u, v);",
        "        return;",
        "    }",
        "    int mid = (l + r) / 2;",
        "    int save = uf.st.size();",
        "    for (int i = mid + 1; i <= r; i++) {",
        "        auto [t, c, id, u, v] = qs[i];",
        "        if (c == 1 && other[i] < l) { // query covers [l, mid]",
        "            uf.merge(u, v);",
        "        } ",
        "    }",
        "    dco(l, mid);",
        "    uf.rollback(save);",
        "    for (int i = l; i <= mid; i++) {",
        "        auto [t, c, id, u, v] = qs[i];",
        "        if (c == 0 && other[i] > r) { // query covers [mid + 1, r]",
        "            uf.merge(u, v);",
        "        } ",
        "    }",
        "    dco(mid + 1, r);",
        "    uf.rollback(save);",
        "}",
        "",
        "void solve() {",
        "    cin >> n >> m; uf.init(n);",
        "    for (int i = 0; i < m; i++) {",
        "        int u, v, s, e; cin >> u >> v >> s >> e;",
        "        qs.push_back({s, 0, -1, u, v});",
        "        qs.push_back({e + 1, 1, -1, u, v});",
        "    }",
        "    cin >> q;",
        "    for (int i = 0; i < q; i++) {",
        "        int u, v, t; cin >> u >> v >> t;",
        "        qs.push_back({t, 2, i, u, v});",
        "    }",
        "    sort(qs.begin(), qs.end());",
        "    for (int i = 0; i < qs.size(); i++) {",
        "        auto [t, c, id, u, v] = qs[i];",
        "        if (c == 0) {",
        "            mp[{u, v}] = i;",
        "            other[i] = qs.size();",
        "        }",
        "        if (c == 1) {",
        "            other[mp[{u, v}]] = i;",
        "            other[i] = mp[{u, v}];",
        "        }",
        "    }",
        "    dco(0, qs.size() - 1);",
        "    for (int i = 0; i < q; i++) {",
        "        cout << (ans[i] ? \"Y\" : \"N\") << \"\\n\";",
        "    }",
        "}",
        "",
        "int main() {",
        "    ios_base::sync_with_stdio(0);",
        "    cin.tie(0); cout.tie(0);",
        "    // freopen(\"input.txt\", \"r\", stdin);",
        "    // freopen(\"output.txt\", \"w\", stdout);",
        "",
        "    int tc; tc = 1;",
        "    for (int t = 1; t <= tc; t++) {",
        "        // cout << \"Case #\" << t  << \": \";",
        "        solve();",
        "    }",
        "}"
      }),
      i(0),  -- Final cursor position
    }),

    -- [String Processing] KMP (Prefix function).cpp: Given a string s (with length n) and a pattern p (with length m), find all occurrence of p in s
    s("kmp_pref", {
      t({
        "#include <bits/stdc++.h>",
        " ",
        "using namespace std;",
        " ",
        "#define ar array",
        "#define ll long long",
        " ",
        "const int MAX_N = 1e5 + 5;",
        "const ll MOD = 1e9 + 7;",
        "const ll INF = 1e9;",
        " ",
        "// f[i] = length of the longest proper prefix of the substring s[0...i] which is also a suffix of this substring",
        "vector<int> prefix_func(string s) {",
        "    int n = s.size();",
        "    vector<int> f(n); ",
        "    for (int i = 1; i < n; i++) {",
        "        int j = f[i - 1];",
        "        while (j && s[i] != s[j]) j = f[j - 1];",
        "        f[i] = j + (s[i] == s[j]);",
        "    }",
        "    return f;",
        "}",
        " ",
        "int cnt_occ(string s, string t) {",
        "    string ts = t + \"#\" + s;",
        "    int n = t.size(), m = s.size(), nm = ts.size();",
        "    auto f = prefix_func(ts);",
        "    int res = 0;",
        "    for (int i = n + 1; i < nm; i++) res += (f[i] == n);",
        "    return res;",
        "}",
        " ",
        "void solve() {",
        "    string s, t; cin >> s >> t;",
        "    cout << cnt_occ(s, t) << \"\\n\";",
        "}",
        " ",
        "int main() {",
        "    ios_base::sync_with_stdio(0);",
        "    cin.tie(0); cout.tie(0);",
        "    int tc = 1;",
        "    // cin >> tc;",
        "    for (int t = 1; t <= tc; t++) {",
        "        // cout << \"Case #\" << t << \": \";",
        "        solve();",
        "    }",
        "}"
      }),
      i(0),  -- Final cursor position
    }),

    -- [String Processing] String Hashing (Rabin-Karp).cpp: String Hashing
    s("rabinkarp_rabi", {
      t({
        "#include <bits/stdc++.h>",
        "",
        "using namespace std;",
        "",
        "#define ar array",
        "#define ll long long",
        "",
        "const int MAX_N = 1e5 + 5;",
        "const ll MOD = 1e9 + 7;",
        "const ll INF = 1e9;",
        "",
        "mt19937 rng(chrono::steady_clock::now().time_since_epoch().count());",
        "ll rand(ll l, ll r) {return uniform_int_distribution(l, r)(rng);}",
        "const int BASE = rand(300, 1e9);",
        "const int NUM_MOD = 2;",
        "const ll MODS[] = {(int)1e9 + 2277, (int)1e9 + 5277};",
        "struct Hash {",
        "    vector<ll> H[NUM_MOD], P[NUM_MOD];",
        "    Hash(string s) {",
        "        for (int i = 0; i < NUM_MOD; i++) {",
        "            P[i].push_back(1);",
        "            H[i].push_back(0);",
        "        }",
        "        for (char c : s) {",
        "            for (int i = 0; i < NUM_MOD; i++) {",
        "                P[i].push_back(P[i].back() * BASE % MODS[i]);",
        "                H[i].push_back((H[i].back() * BASE + c) % MODS[i]);",
        "            }",
        "        }",
        "    } ",
        "    ar<ll,NUM_MOD> operator()(int l, int r) {",
        "        ar<ll,NUM_MOD> res;",
        "        for (int i = 0; i < NUM_MOD; i++) {",
        "            res[i] = (H[i][r + 1] - H[i][l] * P[i][r + 1 - l]) % MODS[i];",
        "            if (res[i] < 0) res[i] += MODS[i];",
        "        }",
        "        return res;",
        "    }",
        "};",
        "",
        "int cnt_occ(string s, string t) {",
        "    int n = s.size(), m = t.size();",
        "    Hash hs(s), ht(t);",
        "    int res = 0;",
        "    for (int i = 0, j = m - 1; j < n; i++, j++) {",
        "        res += (hs(i, j) == ht(0, m - 1));",
        "    }",
        "    return res;",
        "}",
        "",
        "void solve() {",
        "    string s, t; cin >> s >> t;",
        "    cout << cnt_occ(s, t) << \"\\n\";",
        "}",
        "",
        "int main() {",
        "    ios_base::sync_with_stdio(0);",
        "    cin.tie(0); cout.tie(0);",
        "    int tc = 1;",
        "    // cin >> tc;",
        "    for (int t = 1; t <= tc; t++) {",
        "        // cout << \"Case #\" << t << \": \";",
        "        solve();",
        "    }",
        "}"
      }),
      i(0),  -- Final cursor position
    }),

    -- [String Processing] Z-algo (Z function).cpp: Given a string s (with length n) and a pattern p (with length m), find all the occurrence of p in s
    s("zalgo_z_fu", {
      t({
        "#include <bits/stdc++.h>",
        " ",
        "using namespace std;",
        " ",
        "#define ar array",
        "#define ll long long",
        " ",
        "const int MAX_N = 1e5 + 5;",
        "const ll MOD = 1e9 + 7;",
        "const ll INF = 1e9;",
        " ",
        "// f[i] = length of the longest common prefix between s and the substring s[i...n-1]",
        "vector<int> z_func(string s) {",
        "    int n = s.size();",
        "    vector<int> f(n); // f[0] = 0 by default",
        "    for (int i = 1, l = 0, r = 0; i < n; i++) {",
        "        if (i <= r) f[i] = min(r - i + 1, f[i - l]);",
        "        while (i + f[i] < n && s[f[i]] == s[i + f[i]]) f[i]++;",
        "        if (i + f[i] - 1 > r) l = i, r = i + f[i] - 1;",
        "    }",
        "    return f;",
        "}",
        " ",
        "int cnt_occ(string s, string t) {",
        "    string ts = t + \"#\" + s;",
        "    int n = t.size(), m = s.size(), nm = ts.size();",
        "    auto f = z_func(ts);",
        "    int res = 0;",
        "    for (int i = n + 1; i < nm; i++) res += (f[i] == n);",
        "    return res;",
        "}",
        " ",
        "void solve() {",
        "    string s, t; cin >> s >> t;",
        "    cout << cnt_occ(s, t) << \"\\n\";",
        "}",
        " ",
        "int main() {",
        "    ios_base::sync_with_stdio(0);",
        "    cin.tie(0); cout.tie(0);",
        "    int tc = 1;",
        "    // cin >> tc;",
        "    for (int t = 1; t <= tc; t++) {",
        "        // cout << \"Case #\" << t << \": \";",
        "        solve();",
        "    }",
        "}"
      }),
      i(0),  -- Final cursor position
    }),
